import { useCallback, useEffect, useRef, useState } from "react";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/components/auth/EmailGate";
import { Link } from "react-router-dom";
import { TableSkeleton } from "@/components/ui/table-skeleton";
import SavedViews from "@/components/workflow/SavedViews";
import ReceivePanel from "@/components/procurement/ReceivePanel";
import VendorStatement from "@/components/procurement/VendorStatement";
import { NotificationTriggers } from "@/components/workflow/NotificationService";
import {
  CheckCircle2,
  ChevronRight,
  FileText,
  Loader2,
  Package,
  Plus,
  Receipt,
  RefreshCw,
  Search,
  Send,
  X,
} from "lucide-react";
import { CcsDateField } from "@/components/ui/ccs-date-field";

const clean = (v) => String(v ?? "").trim();
const uuid = () => crypto.randomUUID();
const usd = (n) => `$${Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const STATUS_LABELS = {
  draft: "Draft",
  sent: "Sent",
  partially_received: "Partial",
  received: "Received",
  cancelled: "Cancelled",
};
const STATUS_STYLES = {
  draft: "bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300",
  sent: "bg-blue-100 text-blue-700 dark:bg-blue-900/60 dark:text-blue-300",
  partially_received: "bg-amber-100 text-amber-700 dark:bg-amber-900/60 dark:text-amber-300",
  received: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/60 dark:text-emerald-300",
  cancelled: "bg-red-100 text-red-700 dark:bg-red-900/60 dark:text-red-300",
};

const inputCls = "min-h-10 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 focus:border-violet-400 focus:outline-none dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100";
const labelCls = "mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400";

const invokeAction = async (sessionToken, body) => {
  const r = await base44.functions.invoke("purchaseOrderAction", { session_token: sessionToken, ...body });
  const data = r?.data || r;
  if (!data?.success) throw new Error(data?.error || "Request failed.");
  return data;
};

function StatusBadge({ status }) {
  const s = clean(status) || "draft";
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-semibold ${STATUS_STYLES[s] || STATUS_STYLES.draft}`}>
      {STATUS_LABELS[s] || s}
    </span>
  );
}

function PoItemsEditor({ items, onChange, stockItems = [] }) {
  const update = (i, patch) => onChange(items.map((row, j) => (j === i ? { ...row, ...patch } : row)));
  return (
    <div>
      <div className="mb-1 grid grid-cols-[1fr_80px_110px_28px] items-center gap-2 text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">
        <span>Item</span><span>Qty</span><span>Unit cost</span><span />
      </div>
      {items.map((row, i) => (
        <div key={i} className="mb-1.5">
          <div className="grid grid-cols-[1fr_80px_110px_28px] items-center gap-2">
            <input className={inputCls} value={row.description} onChange={(e) => update(i, { description: e.target.value })} placeholder="Material / service" />
            <input className={inputCls} type="number" min="0" step="any" value={row.quantity} onChange={(e) => update(i, { quantity: e.target.value })} />
            <input className={inputCls} type="number" min="0" step="any" value={row.unit_cost} onChange={(e) => update(i, { unit_cost: e.target.value })} />
            <button type="button" onClick={() => onChange(items.filter((_, j) => j !== i))} className="text-slate-400 hover:text-red-500"><X className="h-4 w-4" /></button>
          </div>
          {stockItems.length > 0 && (
            <select className={`${inputCls} mt-1 !min-h-8 py-1 text-xs`} value={row.inventory_item_id || ""}
              onChange={(e) => update(i, { inventory_item_id: e.target.value })}>
              <option value="">No stock link — receipt won't change inventory</option>
              {stockItems.map((it) => (
                <option key={it.id} value={it.id}>
                  {[it.material_type, it.product_type, it.size].filter(Boolean).join(" · ") || it.id}
                  {` (on hand ${it.quantity_on_hand})`}
                </option>
              ))}
            </select>
          )}
        </div>
      ))}
      <button type="button" onClick={() => onChange([...items, { description: "", quantity: 1, unit_cost: "" }])}
        className="mt-1 inline-flex items-center gap-1 text-xs font-semibold text-violet-700 hover:underline dark:text-violet-300">
        <Plus className="h-3.5 w-3.5" /> Add line
      </button>
    </div>
  );
}

function PoForm({ sessionToken, purchaseOrder, onClose, onSaved }) {
  const editing = Boolean(purchaseOrder?.id);
  const [form, setForm] = useState({
    po_number: clean(purchaseOrder?.po_number),
    vendor_name: clean(purchaseOrder?.vendor_name),
    vendor_contact: clean(purchaseOrder?.vendor_contact),
    vendor_email: clean(purchaseOrder?.vendor_email),
    vendor_phone: clean(purchaseOrder?.vendor_phone),
    vendor_reference: clean(purchaseOrder?.vendor_reference),
    work_order_id: clean(purchaseOrder?.work_order_id),
    estimate_id: clean(purchaseOrder?.estimate_id),
    opportunity_id: clean(purchaseOrder?.opportunity_id),
    shipping_fee: purchaseOrder?.shipping_fee ?? "",
    order_date: clean(purchaseOrder?.order_date),
    expected_date: clean(purchaseOrder?.expected_date),
    ship_to: clean(purchaseOrder?.ship_to),
    notes: clean(purchaseOrder?.notes),
    internal_notes: clean(purchaseOrder?.internal_notes),
  });
  const [items, setItems] = useState(
    (purchaseOrder?.line_items || []).map((r) => ({ description: r.description || "", quantity: r.quantity ?? 1, unit_cost: r.unit_cost ?? "", inventory_item_id: r.inventory_item_id || "" }))
      .length ? purchaseOrder.line_items.map((r) => ({ description: r.description || "", quantity: r.quantity ?? 1, unit_cost: r.unit_cost ?? "", inventory_item_id: r.inventory_item_id || "" }))
        : [{ description: "", quantity: 1, unit_cost: "", inventory_item_id: "" }]
  );
  const [stockItems, setStockItems] = useState([]);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const keyRef = useRef(uuid());
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const subtotal = items.reduce((s, r) => s + (Number(r.quantity) || 0) * (Number(r.unit_cost) || 0), 0);

  useEffect(() => {
    let live = true;
    base44.functions.invoke("inventoryAction", { session_token: sessionToken, action: "list_stock" })
      .then((r) => { const d = r?.data || r; if (live && d?.success) setStockItems(d.items || []); })
      .catch(() => {});
    return () => { live = false; };
  }, [sessionToken]);

  const save = async () => {
    if (!clean(form.vendor_name)) { setError("A vendor name is required."); return; }
    if (saving) return;
    setSaving(true);
    setError("");
    try {
      const fields = {
        ...Object.fromEntries(Object.entries(form).map(([k, v]) => [k, typeof v === "string" ? clean(v) : v])),
        shipping_fee: Number(form.shipping_fee) || 0,
        line_items: items.filter((r) => clean(r.description)).map((r) => ({
          description: clean(r.description), quantity: Number(r.quantity) || 0, unit_cost: Number(r.unit_cost) || 0,
          inventory_item_id: clean(r.inventory_item_id),
        })),
      };
      if (editing) {
        await invokeAction(sessionToken, { action: "update_purchase_order", purchase_order_id: purchaseOrder.id, baseline: purchaseOrder, fields });
      } else {
        await invokeAction(sessionToken, { action: "create_purchase_order", creation_request_key: keyRef.current, fields });
      }
      onSaved?.();
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "Save failed.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-950/50 p-4" onClick={onClose}>
      <div className="my-8 w-full max-w-3xl rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-700 dark:bg-slate-900" onClick={(e) => e.stopPropagation()}>
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-lg font-bold text-slate-900 dark:text-slate-100">{editing ? `Edit ${purchaseOrder.po_number}` : "New Purchase Order"}</h2>
          <button type="button" onClick={onClose} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-slate-800"><X className="h-5 w-5" /></button>
        </div>
        <div className="grid gap-3 md:grid-cols-4">
          <div><label className={labelCls}>Vendor *</label><input className={inputCls} value={form.vendor_name} onChange={set("vendor_name")} /></div>
          <div><label className={labelCls}>Contact</label><input className={inputCls} value={form.vendor_contact} onChange={set("vendor_contact")} /></div>
          <div><label className={labelCls}>Email</label><input className={inputCls} value={form.vendor_email} onChange={set("vendor_email")} /></div>
          <div><label className={labelCls}>Phone</label><input className={inputCls} value={form.vendor_phone} onChange={set("vendor_phone")} /></div>
        </div>
        <div className="mt-3 grid gap-3 md:grid-cols-4">
          <div><label className={labelCls}>PO #</label><input className={inputCls} value={form.po_number} onChange={set("po_number")} placeholder="Auto" /></div>
          <div><label className={labelCls}>Vendor ref #</label><input className={inputCls} value={form.vendor_reference} onChange={set("vendor_reference")} /></div>
          <div><label className={labelCls}>Order date</label><CcsDateField className={inputCls} value={form.order_date} onChange={set("order_date")} /></div>
          <div><label className={labelCls}>Expected</label><CcsDateField className={inputCls} value={form.expected_date} onChange={set("expected_date")} /></div>
        </div>
        <div className="mt-4"><label className={labelCls}>Line items</label><PoItemsEditor items={items} onChange={setItems} stockItems={stockItems} /></div>
        <div className="mt-3 grid gap-3 md:grid-cols-4">
          <div><label className={labelCls}>Shipping $</label><input className={inputCls} type="number" min="0" step="any" value={form.shipping_fee} onChange={set("shipping_fee")} /></div>
          <div className="md:col-span-2"><label className={labelCls}>Ship to</label><input className={inputCls} value={form.ship_to} onChange={set("ship_to")} placeholder="Shop / job site" /></div>
          <div className="flex items-end pb-1 text-sm font-semibold text-slate-700 dark:text-slate-200">Total: {usd(subtotal + (Number(form.shipping_fee) || 0))}</div>
        </div>
        <details className="mt-3">
          <summary className="cursor-pointer text-xs font-semibold text-slate-500 dark:text-slate-400">Job links (optional)</summary>
          <div className="mt-2 grid grid-cols-1 gap-3 md:grid-cols-3">
            <div><label className={labelCls}>WorkOrder ID</label><input className={inputCls} value={form.work_order_id} onChange={set("work_order_id")} /></div>
            <div><label className={labelCls}>Estimate ID</label><input className={inputCls} value={form.estimate_id} onChange={set("estimate_id")} /></div>
            <div><label className={labelCls}>Opportunity ID</label><input className={inputCls} value={form.opportunity_id} onChange={set("opportunity_id")} /></div>
          </div>
        </details>
        <div className="mt-3 grid gap-3 md:grid-cols-2">
          <div><label className={labelCls}>Vendor notes</label><textarea className={`${inputCls} min-h-14`} value={form.notes} onChange={set("notes")} /></div>
          <div><label className={labelCls}>Internal notes</label><textarea className={`${inputCls} min-h-14`} value={form.internal_notes} onChange={set("internal_notes")} /></div>
        </div>
        {error && <div className="mt-3 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</div>}
        <div className="mt-4 flex justify-end gap-2">
          <button type="button" onClick={onClose} className="min-h-10 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-600 dark:border-slate-600 dark:text-slate-300">Cancel</button>
          <button type="button" onClick={save} disabled={saving} className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white hover:bg-violet-700 disabled:opacity-60">
            {saving && <Loader2 className="h-4 w-4 animate-spin" />}{editing ? "Save changes" : "Create PO"}
          </button>
        </div>
      </div>
    </div>
  );
}

function PoDetail({ sessionToken, purchaseOrderId, onClose, onChanged }) {
  const [detail, setDetail] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [editing, setEditing] = useState(false);
  const [showVendorStatement, setShowVendorStatement] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      setDetail(await invokeAction(sessionToken, { action: "get_purchase_order", purchase_order_id: purchaseOrderId }));
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "Load failed.");
    } finally {
      setLoading(false);
    }
  }, [sessionToken, purchaseOrderId]);

  useEffect(() => { load(); }, [load]);

  const po = detail?.purchase_order;
  const canReceive = ["sent", "partially_received"].includes(clean(po?.status));

  const run = async (label, body) => {
    if (busy) return;
    setBusy(label);
    setError("");
    setNotice("");
    try {
      const data = await invokeAction(sessionToken, body);
      // Unified alerts: po_received / po_backordered fire on the verified
      // receive result — a full receive notifies "received", a receipt that
      // leaves open quantity notifies "backordered". Fire-and-forget.
      if (body?.action === "receive_items" && data?.purchase_order?.id) {
        try {
          const nextStatus = clean(data.purchase_order.status);
          if (nextStatus === "received") void NotificationTriggers.purchaseOrderReceived(data.purchase_order);
          else if (nextStatus === "partially_received") void NotificationTriggers.purchaseOrderBackordered(data.purchase_order);
        } catch { /* notify is best-effort */ }
      }
      if (Array.isArray(data?.stock_warnings) && data.stock_warnings.length > 0) {
        setNotice(`Received, but ${data.stock_warnings.length} stock update(s) need attention: ${data.stock_warnings.join(" ")}`);
      }
      await load();
      onChanged?.();
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "Action failed.");
    } finally {
      setBusy("");
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-950/50 p-4" onClick={onClose}>
      <div className="my-8 w-full max-w-3xl rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-700 dark:bg-slate-900" onClick={(e) => e.stopPropagation()}>
        {loading && !detail ? (
          <div className="flex items-center justify-center py-16 text-slate-500"><Loader2 className="mr-2 h-5 w-5 animate-spin" />Loading…</div>
        ) : !po ? (
          <div className="py-8 text-center text-sm text-red-600">{error || "Purchase order not found."}</div>
        ) : (
          <>
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <div className="flex items-center gap-2">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-slate-100">{po.po_number}</h2>
                  <StatusBadge status={po.status} />
                  {po.payment_status === "paid" && (
                    <span className="rounded-full bg-emerald-100 px-2 py-0.5 text-xs font-semibold text-emerald-700 dark:bg-emerald-900/60 dark:text-emerald-300">Paid</span>
                  )}
                  {po.payment_status === "invoiced" && (
                    <span className="rounded-full bg-amber-100 px-2 py-0.5 text-xs font-semibold text-amber-700 dark:bg-amber-900/60 dark:text-amber-300">Vendor bill received</span>
                  )}
                </div>
                <div className="mt-0.5 text-sm font-medium text-slate-700 dark:text-slate-200">{po.vendor_name}</div>
                <div className="mt-0.5 text-xs text-slate-500">
                  {po.order_date ? `Ordered ${po.order_date}` : "Not ordered"}{po.expected_date ? ` · Expected ${po.expected_date}` : ""}{po.vendor_reference ? ` · Ref ${po.vendor_reference}` : ""}
                </div>
              </div>
              <button type="button" onClick={onClose} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-slate-800"><X className="h-5 w-5" /></button>
            </div>

            <div className="mt-4">
              <ReceivePanel
                po={po}
                sessionToken={sessionToken}
                canReceive={canReceive}
                busy={busy}
                onReceive={(lines) => run("receive", { action: "receive_items", purchase_order_id: po.id, lines })}
              />
            </div>
            <div className="mt-2 text-right text-sm">
              <span className="mr-4">Subtotal: <span className="font-medium">{usd(po.subtotal)}</span></span>
              <span className="mr-4">Shipping: <span className="font-medium">{usd(po.shipping_fee)}</span></span>
              <span className="text-base font-bold text-slate-900 dark:text-slate-100">Total: {usd(po.total)}</span>
            </div>

            <div className="mt-3 text-xs text-slate-500">
              {po.ship_to && <div>Ship to: {po.ship_to}</div>}
              {po.work_order_id && <div>WorkOrder: <Link className="text-violet-600 hover:underline dark:text-violet-300" to={`/JobWorkspace?wo=${po.work_order_id}`}>{po.work_order_id}</Link></div>}
              {po.estimate_id && <div>Estimate: <Link className="text-violet-600 hover:underline dark:text-violet-300" to={`/EstimateDetail?id=${po.estimate_id}`}>{po.estimate_id}</Link></div>}
              {po.opportunity_id && <div>Opportunity: <Link className="text-violet-600 hover:underline dark:text-violet-300" to={`/Opportunities?open=${po.opportunity_id}`}>{po.opportunity_id}</Link></div>}
              {po.notes && <div className="mt-1 text-sm text-slate-600 dark:text-slate-300">{po.notes}</div>}
            </div>

            <div className="mt-4 flex flex-wrap items-center gap-2">
              <button type="button" onClick={() => setShowVendorStatement(true)} disabled={Boolean(busy)}
                title="Printable per-vendor statement — all POs, expected vs received, status rollup"
                className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-600 hover:bg-slate-50 dark:border-slate-600 dark:text-slate-300 dark:hover:bg-slate-800">
                <FileText className="h-4 w-4" />Vendor statement
              </button>
              {po.status === "draft" && (
                <>
                  <button type="button" onClick={() => run("send", { action: "mark_sent", purchase_order_id: po.id })} disabled={Boolean(busy)}
                    className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-60">
                    {busy === "send" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}Mark sent
                  </button>
                  <button type="button" onClick={() => setEditing(true)}
                    className="min-h-10 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-600 dark:border-slate-600 dark:text-slate-300">Edit</button>
                </>
              )}
              {po.payment_status !== "paid" && po.payment_status !== "invoiced" && ["sent", "partially_received", "received"].includes(po.status) && (
                <button type="button" onClick={() => {
                  const vendor_invoice_number = prompt("Vendor invoice/bill number (optional):", po.vendor_invoice_number || "");
                  if (vendor_invoice_number !== null) run("invoice", { action: "mark_invoiced", purchase_order_id: po.id, vendor_invoice_number });
                }} disabled={Boolean(busy)}
                  className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-amber-500 px-4 text-sm font-semibold text-white hover:bg-amber-600 disabled:opacity-60">
                  {busy === "invoice" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Receipt className="h-4 w-4" />}Vendor bill
                </button>
              )}
              {po.payment_status === "invoiced" && (
                <button type="button" onClick={() => {
                  const paid_amount = prompt("Amount paid:", String(po.total || ""));
                  if (paid_amount !== null) run("paid", { action: "mark_paid", purchase_order_id: po.id, paid_amount: Number(paid_amount) || undefined });
                }} disabled={Boolean(busy)}
                  className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-emerald-600 px-4 text-sm font-semibold text-white hover:bg-emerald-700 disabled:opacity-60">
                  {busy === "paid" ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}Mark paid
                </button>
              )}
              {po.payment_status === "paid" && po.paid_amount > 0 && (
                <span className="text-xs font-semibold text-emerald-600">Paid {usd(po.paid_amount)}{po.paid_date ? ` on ${po.paid_date}` : ""}</span>
              )}
              {!["received", "cancelled"].includes(po.status) && (
                <button type="button" onClick={() => { if (confirm(`Cancel ${po.po_number}?`)) run("cancel", { action: "cancel_purchase_order", purchase_order_id: po.id }); }} disabled={Boolean(busy)}
                  className="min-h-10 rounded-xl border border-red-300 px-4 text-sm font-semibold text-red-600 hover:bg-red-50 disabled:opacity-60 dark:border-red-800 dark:text-red-400">
                  Cancel PO
                </button>
              )}
            </div>
            {error && <div className="mt-3 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</div>}
            {notice && <div className="mt-3 rounded-xl bg-amber-50 px-3 py-2 text-sm font-medium text-amber-800 dark:bg-amber-950/40 dark:text-amber-300">{notice}</div>}
     </>
        )}
      </div>
      {editing && po && (
        <PoForm sessionToken={sessionToken} purchaseOrder={po} onClose={() => setEditing(false)}
          onSaved={async () => { setEditing(false); await load(); onChanged?.(); }} />
      )}
      {showVendorStatement && po && (
        <VendorStatement sessionToken={sessionToken} vendorName={po.vendor_name} onClose={() => setShowVendorStatement(false)} />
      )}
    </div>
  );
}

export default function PurchaseOrders() {
  const { sessionToken, isRegistered } = useAuth();
  const [purchaseOrders, setPurchaseOrders] = useState([]);
  const [status, setStatus] = useState("");
  const [query, setQuery] = useState("");
  const [viewName, setViewName] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [showCreate, setShowCreate] = useState(() => {
    // ?draft_item=<inventory_item_id> opens a new PO prefilled with the
    // low-stock item (linked from the attention feed's low-stock section).
    const id = new URLSearchParams(window.location.search).get("draft_item");
    return Boolean(id && String(id).trim());
  });
  const draftItemId = new URLSearchParams(window.location.search).get("draft_item") || "";
  const [openId, setOpenId] = useState(() => new URLSearchParams(window.location.search).get("po") || "");

  const load = useCallback(async () => {
    if (!sessionToken) return;
    setLoading(true);
    setError("");
    try {
      const data = await invokeAction(sessionToken, { action: "list_purchase_orders", status, query });
      setPurchaseOrders(data.purchase_orders || []);
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "Load failed.");
    } finally {
      setLoading(false);
    }
  }, [sessionToken, status, query]);

  useEffect(() => {
    const t = setTimeout(load, 200);
    return () => clearTimeout(t);
  }, [load]);

  if (!isRegistered) return null;

  const openValue = purchaseOrders.filter((p) => ["sent", "partially_received"].includes(p.status)).reduce((s, p) => s + (Number(p.total) || 0), 0);
  const todayStr = new Date().toISOString().slice(0, 10);
  const isOverdue = (p) => ["sent", "partially_received"].includes(p.status) && p.expected_date && p.expected_date < todayStr;
  const overdueCount = purchaseOrders.filter(isOverdue).length;
  const woParam = new URLSearchParams(window.location.search).get("wo") || "";
  const visibleOrders = woParam ? purchaseOrders.filter((p) => p.work_order_id === woParam) : purchaseOrders;

  return (
    <div className="mx-auto max-w-6xl p-4 md:p-6">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div>
          <div className="flex items-center gap-2">
            <Package className="h-5 w-5 text-violet-600" />
            <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100">Purchase Orders</h1>
          </div>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            Vendor POs and receiving.{openValue > 0 ? ` Open PO value: ${usd(openValue)}.` : ""}{overdueCount > 0 ? ` ${overdueCount} overdue.` : ""}
          </p>
        </div>
        <div className="flex gap-2">
          <button type="button" onClick={load} className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-300 px-3 text-sm font-semibold text-slate-600 dark:border-slate-600 dark:text-slate-300">
            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />Refresh
          </button>
          <button type="button" onClick={() => setShowCreate(true)} className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white hover:bg-violet-700">
            <Plus className="h-4 w-4" />New PO
          </button>
        </div>
      </div>

      <div className="mb-3 flex flex-wrap items-center gap-2">
        <div className="relative min-w-52 flex-1">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input className={`${inputCls} pl-9`} value={query} onChange={(e) => { setViewName(""); setQuery(e.target.value); }} placeholder="Search PO # or vendor…" />
        </div>
        <div className="flex flex-wrap gap-1.5">
          {["", "draft", "sent", "partially_received", "received", "cancelled"].map((s) => (
            <button type="button" key={s || "all"} onClick={() => { setViewName(""); setStatus(s); }}
              className={`min-h-9 rounded-full px-3 text-xs font-semibold ${status === s ? "bg-violet-600 text-white" : "border border-slate-300 text-slate-600 dark:border-slate-600 dark:text-slate-300"}`}>
              {s ? STATUS_LABELS[s] : "All"}
            </button>
          ))}
        </div>
        <SavedViews
          storageKey="views.purchase_orders"
          getState={() => ({ status, query })}
          activeName={viewName}
          onApply={(s, name) => { setStatus(s.status || ""); setQuery(s.query || ""); setViewName(name || ""); }}
        />
      </div>

      {woParam && (
        <div className="mb-3 flex items-center gap-2 rounded-xl bg-sky-50 px-3 py-2 text-sm font-medium text-sky-800 dark:bg-sky-950/40 dark:text-sky-300">
          Filtered to this job's purchase orders.
          <a href="/PurchaseOrders" className="ml-auto text-xs font-semibold text-sky-600 hover:underline">Show all</a>
        </div>
      )}
      {error && <div className="mb-3 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</div>}

      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900">
        {loading && purchaseOrders.length === 0 ? (
          <TableSkeleton columns={6} />
        ) : visibleOrders.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-slate-500">
            <Package className="mb-2 h-8 w-8 text-slate-300 dark:text-slate-600" />
            No purchase orders yet.
          </div>
        ) : (
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-xs font-semibold uppercase text-slate-500 dark:bg-slate-800 dark:text-slate-400">
              <tr>
                <th className="px-4 py-2.5">PO #</th><th className="px-4 py-2.5">Vendor</th>
                <th className="px-4 py-2.5">Expected</th><th className="px-4 py-2.5 text-right">Total</th>
                <th className="px-4 py-2.5">Status</th><th className="px-2 py-2.5" />
              </tr>
            </thead>
            <tbody>
              {visibleOrders.map((po) => (
                <tr key={po.id} onClick={() => setOpenId(po.id)} className="cursor-pointer border-t border-slate-100 hover:bg-violet-50/50 dark:border-slate-800 dark:hover:bg-slate-800/50">
                  <td className="px-4 py-2.5 font-semibold text-slate-900 dark:text-slate-100">{po.po_number}</td>
                  <td className="px-4 py-2.5 text-slate-700 dark:text-slate-300">{po.vendor_name}</td>
                  <td className="px-4 py-2.5 text-slate-500">
                    {po.expected_date || "—"}
                    {isOverdue(po) && <span className="ml-1.5 inline-flex rounded-full bg-red-100 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-red-700 dark:bg-red-950/60 dark:text-red-300">Overdue</span>}
                  </td>
                  <td className="px-4 py-2.5 text-right font-medium">{usd(po.total)}</td>
                  <td className="px-4 py-2.5"><StatusBadge status={po.status} /></td>
                  <td className="px-2 py-2.5 text-slate-400"><ChevronRight className="h-4 w-4" /></td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {showCreate && <PoForm sessionToken={sessionToken} purchaseOrder={draftItemId ? { line_items: [{ inventory_item_id: draftItemId, quantity: 1 }] } : undefined} onClose={() => setShowCreate(false)} onSaved={() => { setShowCreate(false); load(); }} />}
      {openId && <PoDetail sessionToken={sessionToken} purchaseOrderId={openId} onClose={() => setOpenId("")} onChanged={load} />}
    </div>
  );
}

import { useCallback, useEffect, useState } from "react";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/components/auth/EmailGate";
import ReconcileWizard from "@/components/reconciliation/ReconcileWizard";
import LocationsPanel from "@/components/reconciliation/LocationsPanel";
import { staffEntities } from "@/components/staff/staffEntities";
import { BUCKET_LABELS, TENDER_BUCKETS } from "@/components/reconciliation/reconciliationModel";
import {
  ChevronRight,
  Download,
  Loader2,
  Plus,
  RefreshCw,
  Scale,
  Vault,
  X,
} from "lucide-react";
import { loadGlLookup } from "@/components/shared/loadGlLookup";
import { downloadCsv } from "@/components/shared/exportCsv";
import {
  GL_EXPORT_HEADERS,
  glExportRows,
  paymentsToGlEntries,
} from "@/components/shared/glExport";

const clean = (v) => String(v ?? "").trim();
const usd = (n) => `$${Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const inputCls = "min-h-10 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 focus:border-violet-400 focus:outline-none dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100";

const invokeAction = async (sessionToken, body) => {
  const r = await base44.functions.invoke("manageReconciliation", { session_token: sessionToken, ...body });
  const data = r?.data || r;
  if (!data?.success) throw new Error(data?.error || "Request failed.");
  return data;
};

const fmtDate = (iso) => {
  const d = clean(iso);
  if (!d) return "—";
  const parsed = new Date(d.length === 10 ? `${d}T12:00:00` : d);
  return Number.isNaN(parsed.getTime()) ? d : parsed.toLocaleDateString();
};

const VarianceBadge = ({ value }) => {
  const v = Number(value) || 0;
  if (Math.abs(v) < 0.005) return <span className="inline-flex rounded-full bg-emerald-100 px-2.5 py-0.5 text-xs font-semibold text-emerald-700 dark:bg-emerald-900/60 dark:text-emerald-300">Balanced</span>;
  return (
    <span className={`inline-flex rounded-full px-2.5 py-0.5 text-xs font-semibold ${v > 0 ? "bg-blue-100 text-blue-700 dark:bg-blue-900/60 dark:text-blue-300" : "bg-red-100 text-red-700 dark:bg-red-900/60 dark:text-red-300"}`}>
      {v > 0 ? "Over" : "Short"} {usd(Math.abs(v))}
    </span>
  );
};

function BatchDetail({ sessionToken, batchId, onClose }) {
  const [detail, setDetail] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [glNote, setGlNote] = useState("");
  const [glBusy, setGlBusy] = useState(false);

  useEffect(() => {
    let active = true;
    setLoading(true);
    invokeAction(sessionToken, { action: "get_batch", batch_id: batchId })
      .then((d) => active && setDetail(d))
      .catch((e) => active && setError(e?.response?.data?.error || e?.message || "Load failed."))
      .finally(() => active && setLoading(false));
    return () => { active = false; };
  }, [sessionToken, batchId]);

  const batch = detail?.batch;
  const payments = detail?.payments || [];

  // GL export: one receipt journal line per swept payment. gl_account resolves
  // through the MarkupCategory/Inventory/PartTemplate mappings; unmapped rows
  // still export and are counted so Manage Accounts can be completed.
  const downloadGl = async () => {
    if (glBusy || payments.length === 0) return;
    setGlBusy(true);
    setGlNote("");
    try {
      const lookup = await loadGlLookup();
      const { rows, unmapped } = glExportRows(paymentsToGlEntries({ payments, batch }), lookup);
      const name = clean(batch?.batch_number) || "batch";
      downloadCsv(`gl-export-${name}.csv`, GL_EXPORT_HEADERS, rows);
      setGlNote(unmapped
        ? `${unmapped} of ${rows.length} rows exported without a GL account — map categories/items in Manage Accounts.`
        : `${rows.length} rows exported — all GL-mapped.`);
    } catch (e) {
      setGlNote(e?.message || "GL export failed.");
    } finally {
      setGlBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-950/50 p-4" onClick={onClose}>
      <div className="my-8 w-full max-w-2xl rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-700 dark:bg-slate-900" onClick={(e) => e.stopPropagation()}>
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-lg font-bold text-slate-900 dark:text-slate-100">{clean(batch?.batch_number) || "Batch"}</h2>
          <div className="flex items-center gap-2">
            <button type="button" onClick={downloadGl} disabled={loading || glBusy || payments.length === 0}
              title="Journal-style CSV (date, memo, entity_ref, gl_account, debit, credit) for this batch's receipts"
              className="inline-flex items-center gap-1.5 rounded-lg border border-slate-300 px-2.5 py-1.5 text-xs font-semibold text-slate-600 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-600 dark:text-slate-300 dark:hover:bg-slate-800">
              {glBusy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />}
              Download GL export
            </button>
            <button onClick={onClose} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-slate-800"><X className="h-5 w-5" /></button>
          </div>
        </div>
        {loading ? (
          <div className="flex items-center justify-center py-12 text-slate-500"><Loader2 className="mr-2 h-5 w-5 animate-spin" />Loading batch…</div>
        ) : error ? (
          <div className="rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</div>
        ) : batch ? (
          <>
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
              {[
                ["Expected", usd(batch.expected_total)],
                ["Collected", usd(batch.collected_total)],
                ["Cash adj.", usd(batch.cash_adjustment)],
                ["Variance", usd(batch.variance)],
              ].map(([label, val]) => (
                <div key={label} className="rounded-xl border border-slate-200 p-3 dark:border-slate-700">
                  <div className="text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">{label}</div>
                  <div className="text-lg font-bold text-slate-900 dark:text-slate-100">{val}</div>
                </div>
              ))}
            </div>
            <div className="mt-3 grid gap-1 text-sm text-slate-600 dark:text-slate-300">
              <div><span className="font-semibold">Location:</span> {clean(batch.location) || "—"}</div>
              <div><span className="font-semibold">Closed:</span> {fmtDate(batch.closed_at)} · by {clean(batch.created_by) || "—"}</div>
              {clean(batch.adjustment_note) && <div><span className="font-semibold">Adjustment note:</span> {batch.adjustment_note}</div>}
              {clean(batch.notes) && <div><span className="font-semibold">Notes:</span> {batch.notes}</div>}
            </div>
            {batch.method_totals && Object.keys(batch.method_totals).length > 0 && (
              <div className="mt-3 overflow-hidden rounded-xl border border-slate-200 dark:border-slate-700">
                <table className="w-full text-sm">
                  <thead className="bg-slate-50 text-left text-xs font-semibold uppercase text-slate-500 dark:bg-slate-800 dark:text-slate-400">
                    <tr><th className="px-4 py-2">Tender</th><th className="px-4 py-2 text-right">Expected</th><th className="px-4 py-2 text-right">Counted</th></tr>
                  </thead>
                  <tbody>
                    {TENDER_BUCKETS.map((b) => (
                      <tr key={b} className="border-t border-slate-100 dark:border-slate-800">
                        <td className="px-4 py-1.5 font-medium">{BUCKET_LABELS[b]}</td>
                        <td className="px-4 py-1.5 text-right">{usd(batch.method_totals?.[b]?.expected)}</td>
                        <td className="px-4 py-1.5 text-right">{usd(batch.method_totals?.[b]?.counted)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <h3 className="mt-4 text-sm font-bold text-slate-900 dark:text-slate-100">Payments swept ({payments.length})</h3>
            <div className="mt-1 max-h-56 overflow-y-auto rounded-xl border border-slate-200 dark:border-slate-700">
              <table className="w-full text-xs">
                <tbody>
                  {payments.map((p) => (
                    <tr key={p.id} className="border-t border-slate-100 first:border-t-0 dark:border-slate-800">
                      <td className="px-3 py-1.5 text-slate-500">{p.paid_date || "—"}</td>
                      <td className="px-3 py-1.5 font-medium text-slate-800 dark:text-slate-200">{p.invoice_number || p.invoice_id || "—"}</td>
                      <td className="px-3 py-1.5 text-slate-600 dark:text-slate-300">{p.customer_display_name || "—"}</td>
                      <td className="px-3 py-1.5 text-slate-500">{BUCKET_LABELS[p.bucket] || p.method}</td>
                      <td className="px-3 py-1.5 text-right font-semibold">{usd(p.amount)}</td>
                    </tr>
                  ))}
                  {payments.length === 0 && <tr><td className="px-3 py-4 text-center text-slate-500">No payments recorded on this batch.</td></tr>}
                </tbody>
              </table>
            </div>
            {glNote && <p className="mt-2 text-xs text-slate-500 dark:text-slate-400">{glNote}</p>}
          </>
        ) : null}
      </div>
    </div>
  );
}

export default function Reconciliation() {
  const { sessionToken, isRegistered, currentUser } = useAuth();
  const [batches, setBatches] = useState([]);
  const [unreconciled, setUnreconciled] = useState([]);
  const [locations, setLocations] = useState([]);
  const [salesLocations, setSalesLocations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [showWizard, setShowWizard] = useState(false);
  const [openId, setOpenId] = useState("");

  const load = useCallback(async () => {
    if (!sessionToken) return;
    setLoading(true);
    setError("");
    try {
      const data = await invokeAction(sessionToken, { action: "bootstrap" });
      setBatches(data.batches || []);
      setUnreconciled(data.unreconciled || []);
      setLocations(data.locations || []);
      // SalesLocation registry -- the wizard's location select reads active
      // rows from here. Until the staff gateways allowlist the entity this
      // resolves to an empty list and the select falls back to past batch
      // locations rather than failing the page.
      const salesLocationRows = await staffEntities.SalesLocation.list("name", 200).catch(() => []);
      setSalesLocations(Array.isArray(salesLocationRows) ? salesLocationRows : []);
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "Load failed.");
    } finally {
      setLoading(false);
    }
  }, [sessionToken]);

  useEffect(() => { load(); }, [load]);

  if (!isRegistered) return null;

  const pendingTotal = unreconciled.reduce((s, p) => s + (Number(p.amount) || 0), 0);

  return (
    <div className="mx-auto max-w-6xl p-4 md:p-6">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100">Reconciliation</h1>
          <p className="text-sm text-slate-500 dark:text-slate-400">Batched cash close — group payments, count tenders, track variance.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={load} className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-300 px-3 text-sm font-semibold text-slate-600 dark:border-slate-600 dark:text-slate-300">
            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />Refresh
          </button>
          <button onClick={() => setShowWizard(true)} disabled={unreconciled.length === 0}
            className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white hover:bg-violet-700 disabled:opacity-60">
            <Plus className="h-4 w-4" />New Reconciliation
          </button>
        </div>
      </div>

      <div className="mb-4 grid grid-cols-2 gap-2 md:grid-cols-3">
        <div className="rounded-xl border border-slate-200 bg-white p-3 dark:border-slate-700 dark:bg-slate-900">
          <div className="text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">Unreconciled</div>
          <div className="text-lg font-bold text-slate-900 dark:text-slate-100">{unreconciled.length} payment{unreconciled.length === 1 ? "" : "s"}</div>
        </div>
        <div className="rounded-xl border border-slate-200 bg-white p-3 dark:border-slate-700 dark:bg-slate-900">
          <div className="text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">Waiting to close</div>
          <div className="text-lg font-bold text-slate-900 dark:text-slate-100">{usd(pendingTotal)}</div>
        </div>
        <div className="rounded-xl border border-slate-200 bg-white p-3 dark:border-slate-700 dark:bg-slate-900">
          <div className="text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">Batches closed</div>
          <div className="text-lg font-bold text-slate-900 dark:text-slate-100">{batches.length}</div>
        </div>
      </div>

      <LocationsPanel locations={salesLocations} isAdmin={currentUser?.role === "admin"} onChanged={load} />

      {error && <div className="mb-3 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</div>}
      {notice && <div className="mb-3 rounded-xl bg-emerald-50 px-3 py-2 text-sm font-medium text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">{notice}</div>}

      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900">
        {loading && batches.length === 0 ? (
          <div className="flex items-center justify-center py-16 text-slate-500"><Loader2 className="mr-2 h-5 w-5 animate-spin" />Loading batches…</div>
        ) : batches.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-slate-500">
            <Vault className="mb-2 h-8 w-8 text-slate-300 dark:text-slate-600" />
            {unreconciled.length === 0
              ? "No reconciliation batches yet — recorded payments will appear here once collected."
              : `No batches yet. ${unreconciled.length} payment${unreconciled.length === 1 ? "" : "s"} (${usd(pendingTotal)}) waiting — start a New Reconciliation to close them.`}
          </div>
        ) : (
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-xs font-semibold uppercase text-slate-500 dark:bg-slate-800 dark:text-slate-400">
              <tr>
                <th className="px-4 py-2.5">Batch</th><th className="px-4 py-2.5">Date</th>
                <th className="px-4 py-2.5">Location</th><th className="px-4 py-2.5 text-right">Payments</th>
                <th className="px-4 py-2.5 text-right">Collected</th><th className="px-4 py-2.5">Variance</th>
                <th className="px-4 py-2.5">By</th><th className="px-2 py-2.5" />
              </tr>
            </thead>
            <tbody>
              {batches.map((b) => (
                <tr key={b.id} onClick={() => setOpenId(b.id)} className="cursor-pointer border-t border-slate-100 hover:bg-violet-50/50 dark:border-slate-800 dark:hover:bg-slate-800/50">
                  <td className="px-4 py-2.5 font-semibold text-slate-900 dark:text-slate-100">
                    <span className="inline-flex items-center gap-1.5"><Scale className="h-3.5 w-3.5 text-violet-500" />{b.batch_number}</span>
                  </td>
                  <td className="px-4 py-2.5 text-slate-500">{fmtDate(b.closed_at)}</td>
                  <td className="px-4 py-2.5 text-slate-700 dark:text-slate-300">{b.location || "—"}</td>
                  <td className="px-4 py-2.5 text-right text-slate-500">{b.payment_count}</td>
                  <td className="px-4 py-2.5 text-right font-medium">{usd(b.collected_total)}</td>
                  <td className="px-4 py-2.5"><VarianceBadge value={b.variance} /></td>
                  <td className="px-4 py-2.5 text-slate-500">{b.created_by || "—"}</td>
                  <td className="px-2 py-2.5 text-slate-400"><ChevronRight className="h-4 w-4" /></td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {showWizard && (
        <ReconcileWizard
          sessionToken={sessionToken}
          payments={unreconciled}
          batches={batches}
          locations={locations}
          salesLocations={salesLocations}
          invoke={invokeAction}
          onClose={() => setShowWizard(false)}
          onClosed={(data) => {
            setShowWizard(false);
            setNotice(`${clean(data?.batch?.batch_number) || "Batch"} closed — ${data?.swept_count ?? 0} payment${(data?.swept_count ?? 0) === 1 ? "" : "s"} swept${data?.skipped_payment_ids?.length ? `, ${data.skipped_payment_ids.length} skipped (changed mid-close)` : ""}.`);
            load();
          }}
        />
      )}
      {openId && <BatchDetail sessionToken={sessionToken} batchId={openId} onClose={() => setOpenId("")} />}
    </div>
  );
}

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/components/auth/EmailGate";
import { Customer } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { loadQuoteDefaults } from "@/components/estimator/quoteDefaults";
import { buildStatement, paymentsFromArCsv } from "@/components/statements/statementModel";
import StatementView from "@/components/statements/StatementView";
import {
  AlertCircle,
  FileText,
  Loader2,
  Mail,
  Printer,
  RefreshCw,
  Search,
  Users,
} from "lucide-react";
import {
  buildNotifyContext,
  resolveCustomerEmail,
  statusGateAllows,
} from "@/components/comms/notifyModel";
import { sendCustomerNotification } from "@/components/comms/notifySend";
import { CcsDateField } from "@/components/ui/ccs-date-field";

const clean = (v) => String(v ?? "").trim();
const today = () => new Date().toISOString().slice(0, 10);

const inputCls =
  "min-h-10 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 focus:border-violet-400 focus:outline-none dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100";
const labelCls =
  "mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400";

// Invoice/Payment are backend-only entities — every read goes through the
// deployed invoicingAction function with the staff session token.
const invokeAction = async (sessionToken, body) => {
  const r = await base44.functions.invoke("invoicingAction", { session_token: sessionToken, ...body });
  const data = r?.data || r;
  if (!data?.success) throw new Error(data?.error || "Request failed.");
  return data;
};

const customerLabel = (c) => clean(c?.company_name) || clean(c?.name) || "Unnamed customer";
const customerActive = (c) => c && c.deleted !== true && !clean(c.merged_into_customer_id);

const matchesQuery = (c, q) => {
  if (!q) return true;
  const hay = [
    c.company_name, c.name, c.contact_first_name, c.contact_last_name,
    c.billing_contact_name, c.contact_email, c.billing_contact_email,
    c.contact_office_phone, c.company_phone,
  ].map((v) => clean(v).toLowerCase()).join("|");
  return hay.includes(q);
};

export default function CustomerStatements() {
  const { sessionToken, isRegistered, currentUser } = useAuth();
  const actor = clean(currentUser?.email || currentUser?.full_name);
  const [query, setQuery] = useState("");
  const [asOf, setAsOf] = useState(today());
  const [selected, setSelected] = useState(() => {
    const id = new URLSearchParams(window.location.search).get("customer");
    return new Set(id && String(id).trim() ? [id] : []);
  });
  const [statements, setStatements] = useState(null);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  useEffect(() => { document.title = "Customer Statements"; }, []);

  const { data: allCustomers = [], isFetching: customersLoading, refetch: refetchCustomers } = useQuery({
    queryKey: ["customer-statements", "customers"],
    enabled: Boolean(sessionToken),
    queryFn: () =>
      loadAllEntityRows({
        entity: Customer,
        sort: "company_name",
        label: "Statement customers",
        cacheTtlMs: 30000,
      }),
  });
  const customers = useMemo(
    () => (allCustomers || []).filter(customerActive),
    [allCustomers]
  );

  const { data: company = null } = useQuery({
    queryKey: ["customer-statements", "company"],
    enabled: Boolean(sessionToken),
    queryFn: () => loadQuoteDefaults().catch(() => null),
    staleTime: 60000,
  });

  const visible = useMemo(
    () => customers.filter((c) => matchesQuery(c, clean(query).toLowerCase())),
    [customers, query]
  );
  const selectedCustomers = useMemo(
    () => customers.filter((c) => selected.has(c.id)),
    [customers, selected]
  );

  const toggle = (id) =>
    setSelected((s) => {
      const next = new Set(s);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });

  const toggleAllVisible = () =>
    setSelected((s) => {
      const next = new Set(s);
      const allOn = visible.length > 0 && visible.every((c) => next.has(c.id));
      if (allOn) visible.forEach((c) => next.delete(c.id));
      else visible.forEach((c) => next.add(c.id));
      return next;
    });

  /**
   * Pull the customer's issued invoices + applied payments, then build the
   * pure statement. list_invoices caps at 250 rows — first try one unfiltered
   * call shared by every target; when the cap is hit, refetch per customer
   * with the company-name query so the server narrows before slicing.
   * Payments come from one export_ar call (payments_csv is uncapped) matched
   * to the customer's invoice numbers.
   */
  const buildForTargets = useCallback(async (targets) => {
    const [first, ar] = await Promise.all([
      invokeAction(sessionToken, { action: "list_invoices" }),
      invokeAction(sessionToken, { action: "export_ar" }).catch(() => ({ payments_csv: "" })),
    ]);
    const payments = paymentsFromArCsv(ar?.payments_csv || "");
    const hitListCap = (first.invoices || []).length >= 250;

    const invoicePools = new Map();
    if (!hitListCap) {
      const byCustomer = new Map();
      for (const inv of first.invoices || []) {
        const cid = clean(inv.customer_id);
        if (!byCustomer.has(cid)) byCustomer.set(cid, []);
        byCustomer.get(cid).push(inv);
      }
      for (const c of targets) invoicePools.set(c.id, byCustomer.get(c.id) || []);
    } else {
      for (const c of targets) {
        const data = await invokeAction(sessionToken, {
          action: "list_invoices",
          query: clean(c.company_name),
        });
        invoicePools.set(
          c.id,
          (data.invoices || []).filter((inv) => clean(inv.customer_id) === c.id)
        );
      }
    }

    const built = targets.map((c) => {
      const invs = invoicePools.get(c.id) || [];
      const numbers = new Set(invs.map((i) => clean(i.invoice_number)).filter(Boolean));
      const custPayments = payments.filter((p) => numbers.has(clean(p.invoice_number)));
      return buildStatement({ customer: c, invoices: invs, payments: custPayments, asOfDate: asOf });
    });
    return { built, hitListCap };
  }, [sessionToken, asOf]);

  const generate = useCallback(async (targets) => {
    if (!sessionToken || !targets.length || busy) return;
    setBusy("generate");
    setError("");
    setNotice("");
    try {
      const { built, hitListCap } = await buildForTargets(targets);
      setStatements(built);
      if (hitListCap) {
        setNotice("More than 250 invoices on file — per-customer lookups were used; very high-volume accounts may still be capped.");
      }
      const withNoActivity = built.filter((s) => s.lines.length === 0).length;
      if (withNoActivity) {
        setNotice((n) => `${n ? `${n} ` : ""}${withNoActivity} of ${built.length} statement${built.length === 1 ? "" : "s"} have no activity on or before ${asOf}.`);
      }
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "Statement generation failed.");
    } finally {
      setBusy("");
    }
  }, [sessionToken, asOf, busy, buildForTargets]);

  // "Email statement" — renders the monthly_statement notification template
  // against the freshly built statement and sends through the sendStaffEmail
  // bridge, then writes the standard OpportunityActivity audit row
  // (details.notify_kind = monthly_statement) so sends are dedupe-able.
  const emailStatement = useCallback(async (customer) => {
    if (!sessionToken || !customer?.id || busy) return;
    setBusy(`email:${customer.id}`);
    setError("");
    setNotice("");
    try {
      const { built } = await buildForTargets([customer]);
      const statement = built[0];
      if (!statement || !statusGateAllows("monthly_statement", statement)) {
        throw new Error(`No statement activity for ${customerLabel(customer)} on or before ${statement?.asOf || asOf}.`);
      }
      const to = resolveCustomerEmail(customer);
      if (!to.includes("@")) {
        throw new Error(`${customerLabel(customer)} has no email address on file.`);
      }
      const ctx = buildNotifyContext({ customer, statement, company });
      const res = await sendCustomerNotification({
        kind: "monthly_statement",
        ctx,
        to,
        sessionToken,
        actor,
        log: {
          targetId: `statement:${customer.id}:${statement.asOf}`,
          targetRef: `Statement as of ${statement.asOf}`,
          customerId: customer.id,
          customerName: customerLabel(customer),
          contactName: ctx.contact_name,
        },
      });
      setNotice(
        `Statement emailed to ${to}.` +
        (res.logError ? ` The log write failed: ${res.logError} — resolve the log before resending.` : "")
      );
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "The statement email could not be sent.");
    } finally {
      setBusy("");
    }
  }, [sessionToken, actor, asOf, busy, buildForTargets, company]);

  if (!isRegistered) return null;

  const allVisibleOn = visible.length > 0 && visible.every((c) => selected.has(c.id));

  return (
    <div className="mx-auto max-w-5xl p-4 md:p-6">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100">Customer Statements</h1>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            CoreBridge-style statement of account — activity ledger, aging and a printable remittance copy.
          </p>
        </div>
        <button type="button" onClick={() => refetchCustomers()}
          className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-300 px-3 text-sm font-semibold text-slate-600 dark:border-slate-600 dark:text-slate-300">
          <RefreshCw className={`h-4 w-4 ${customersLoading ? "animate-spin" : ""}`} />Refresh
        </button>
      </div>

      <div className="mb-4 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900 md:grid-cols-[1fr_170px_auto] md:items-end">
        <div>
          <label className={labelCls}>Find customers</label>
          <div className="relative">
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input className={`${inputCls} pl-9`} value={query} onChange={(e) => setQuery(e.target.value)}
              placeholder="Search company, contact, email…" />
          </div>
        </div>
        <div>
          <label className={labelCls}>Statement as of</label>
          <CcsDateField className={inputCls} value={asOf} onChange={(e) => setAsOf(e.target.value || today())} />
        </div>
        <div className="flex gap-2">
          <button type="button" disabled={!selectedCustomers.length || Boolean(busy)}
            onClick={() => generate(selectedCustomers)}
            className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white hover:bg-violet-700 disabled:opacity-50">
            {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Printer className="h-4 w-4" />}
            {selectedCustomers.length > 1 ? `Generate all (${selectedCustomers.length})` : "Generate"}
          </button>
        </div>
      </div>

      {error && (
        <div className="mb-3 flex items-center gap-2 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">
          <AlertCircle className="h-4 w-4 shrink-0" />{error}
        </div>
      )}
      {notice && (
        <div className="mb-3 rounded-xl bg-amber-50 px-3 py-2 text-sm font-medium text-amber-800 dark:bg-amber-950/40 dark:text-amber-300">
          {notice}
        </div>
      )}

      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900">
        {customersLoading && customers.length === 0 ? (
          <div className="flex items-center justify-center py-16 text-slate-500">
            <Loader2 className="mr-2 h-5 w-5 animate-spin" />Loading customers…
          </div>
        ) : visible.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-slate-500">
            <Users className="mb-2 h-8 w-8 text-slate-300 dark:text-slate-600" />
            {customers.length === 0 ? "No customers yet." : "No customers match your search."}
          </div>
        ) : (
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-xs font-semibold uppercase text-slate-500 dark:bg-slate-800 dark:text-slate-400">
              <tr>
                <th className="w-10 px-3 py-2.5">
                  <input type="checkbox" className="h-4 w-4 align-middle accent-violet-600"
                    title="Select all shown"
                    checked={allVisibleOn} onChange={toggleAllVisible} />
                </th>
                <th className="px-3 py-2.5">Customer</th>
                <th className="px-3 py-2.5">Contact</th>
                <th className="px-3 py-2.5">Terms</th>
                <th className="px-3 py-2.5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {visible.map((c) => {
                const contact = [clean(c.contact_first_name), clean(c.contact_last_name)].filter(Boolean).join(" ")
                  || clean(c.billing_contact_name);
                const on = selected.has(c.id);
                return (
                  <tr key={c.id} onClick={() => toggle(c.id)}
                    className={`cursor-pointer border-t border-slate-100 hover:bg-violet-50/50 dark:border-slate-800 dark:hover:bg-slate-800/50 ${on ? "bg-violet-50/60 dark:bg-violet-950/20" : ""}`}>
                    <td className="px-3 py-2.5" onClick={(e) => e.stopPropagation()}>
                      <input type="checkbox" className="h-4 w-4 accent-violet-600" checked={on} onChange={() => toggle(c.id)} />
                    </td>
                    <td className="px-3 py-2.5">
                      <Link className="font-semibold text-sky-600 hover:underline dark:text-sky-400" to={`/Customer360?id=${c.id}`} onClick={(e) => e.stopPropagation()}>
                        {customerLabel(c)}
                      </Link>
                      {clean(c.contact_email || c.billing_contact_email) && (
                        <div className="text-xs text-slate-500">{clean(c.contact_email) || clean(c.billing_contact_email)}</div>
                      )}
                    </td>
                    <td className="px-3 py-2.5 text-slate-600 dark:text-slate-300">{contact || "—"}</td>
                    <td className="px-3 py-2.5 text-slate-500">{clean(c.terms) || "—"}</td>
                    <td className="px-3 py-2.5 text-right" onClick={(e) => e.stopPropagation()}>
                      <div className="inline-flex items-center gap-1.5">
                        <button type="button" disabled={Boolean(busy)} onClick={() => generate([c])}
                          className="inline-flex min-h-8 items-center gap-1 rounded-lg border border-violet-300 px-2.5 text-xs font-semibold text-violet-700 hover:bg-violet-50 disabled:opacity-50 dark:border-violet-800 dark:text-violet-300">
                          <FileText className="h-3.5 w-3.5" />Statement
                        </button>
                        <button type="button" disabled={Boolean(busy)} onClick={() => emailStatement(c)}
                          title={`Email the ${asOf} statement to ${customerLabel(c)}`}
                          className="inline-flex min-h-8 items-center gap-1 rounded-lg border border-sky-300 px-2.5 text-xs font-semibold text-sky-700 hover:bg-sky-50 disabled:opacity-50 dark:border-sky-800 dark:text-sky-300">
                          {busy === `email:${c.id}` ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Mail className="h-3.5 w-3.5" />}
                          Email statement
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {selected.size > 0 && (
        <p className="mt-3 text-xs text-slate-500 dark:text-slate-400">
          {selected.size} customer{selected.size === 1 ? "" : "s"} selected — Generate all produces a printable stack
          (one page per customer) plus a CSV export of each activity ledger.
        </p>
      )}

      {statements && statements.length > 0 && (
        <StatementView
          statements={statements}
          company={company}
          onClose={() => setStatements(null)}
        />
      )}
    </div>
  );
}

import { Fragment, useCallback, useEffect, useMemo, useState } from "react";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/components/auth/EmailGate";
import { Link } from "react-router-dom";
import SavedViews from "@/components/workflow/SavedViews";
import { TableSkeleton } from "@/components/ui/table-skeleton";
import { downloadCsv } from "@/components/shared/exportCsv";
import ProgressBillingPanel from "@/components/jobcosting/ProgressBillingPanel";
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  BarChart3,
  ChevronRight,
  Clock,
  Loader2,
  RefreshCw,
  Search,
  X,
} from "lucide-react";

const clean = (v) => String(v ?? "").trim();
const usd = (n) => {
  const v = Number(n || 0);
  return `${v < 0 ? "-" : ""}$${Math.abs(v).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};
const hrs = (n) => `${Number(n || 0).toFixed(1)}h`;

const inputCls = "min-h-10 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 focus:border-violet-400 focus:outline-none dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100";

const invokeAction = async (sessionToken, body) => {
  const r = await base44.functions.invoke("jobCostingAction", { session_token: sessionToken, ...body });
  const data = r?.data || r;
  if (!data?.success) throw new Error(data?.error || "Request failed.");
  return data;
};

function MarginCell({ value }) {
  const v = Number(value) || 0;
  return <span className={`font-semibold ${v < 0 ? "text-red-600" : "text-emerald-600"}`}>{usd(v)}</span>;
}

function MarginPct({ job }) {
  const contract = Number(job?.contract_value) || 0;
  if (!contract) return null;
  const pct = ((Number(job?.margin_vs_materials) || 0) / contract) * 100;
  return (
    <span className={`text-[10px] font-semibold ${pct < 0 ? "text-red-500" : "text-emerald-600"}`}>
      {pct.toFixed(1)}%
    </span>
  );
}

function JobDetail({ sessionToken, workOrderId, onClose }) {
  const [detail, setDetail] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    try {
      setDetail(await invokeAction(sessionToken, { action: "get_job_cost", work_order_id: workOrderId }));
      setError("");
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "Load failed.");
    } finally {
      setLoading(false);
    }
  }, [sessionToken, workOrderId]);

  useEffect(() => { load(); }, [load]);

  const j = detail?.job;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-950/50 p-4" onClick={onClose}>
      <div className="my-8 w-full max-w-3xl rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-700 dark:bg-slate-900" onClick={(e) => e.stopPropagation()}>
        {loading && !detail ? (
          <TableSkeleton columns={6} rows={8} />
        ) : !j ? (
          <div className="py-8 text-center text-sm text-red-600">{error || "Job not found."}</div>
        ) : (
          <>
            <div className="flex items-start justify-between">
              <div>
                <h2 className="text-xl font-bold text-slate-900 dark:text-slate-100">
                  <Link className="hover:underline" to={`/JobWorkspace?wo=${workOrderId}`}>{j.title || "Work order"}</Link>
                </h2>
                <div className="mt-0.5 text-sm text-slate-500">
                  {clean(detail?.work_order?.customer_id) ? (
                    <Link className="text-sky-600 hover:underline dark:text-sky-400" to={`/Customer360?id=${detail.work_order.customer_id}`}>{j.client_name}</Link>
                  ) : j.client_name} · {j.current_stage || j.sales_status || "—"}
                </div>
              </div>
              <button type="button" onClick={onClose} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-slate-800"><X className="h-5 w-5" /></button>
            </div>

            <div className="mt-4 grid grid-cols-2 gap-2 md:grid-cols-5">
              {[
                ["Contract", usd(j.contract_value), j.co_delta ? `incl. ${usd(j.co_delta)} CO` : ""],
                ["PO committed", usd(j.po_committed), "materials + services"],
                ["Stock issued", usd(j.stock_issued), "from inventory"],
                ["Labor", hrs(j.labor_hours), "tracked segments"],
                ["Margin vs materials", "", ""],
              ].map(([label, val, sub], i) => (
                <div key={label} className="rounded-xl border border-slate-200 p-3 dark:border-slate-700">
                  <div className="text-xs font-semibold uppercase text-slate-500 dark:text-slate-400">{label}</div>
                  <div className="mt-0.5 text-lg font-bold text-slate-900 dark:text-slate-100">
                    {i === 4 ? <MarginCell value={j.margin_vs_materials} /> : val}
                  </div>
                  {sub && <div className="text-xs text-slate-400">{sub}</div>}
                </div>
              ))}
            </div>
            <div className="mt-2 grid grid-cols-3 gap-2">
              {[["Invoiced", j.invoiced], ["Collected", j.collected], ["Open AR", j.open_ar]].map(([label, val]) => (
                <div key={label} className="rounded-xl border border-slate-200 p-3 text-center dark:border-slate-700">
                  <div className="text-xs font-semibold uppercase text-slate-500 dark:text-slate-400">{label}</div>
                  <div className="text-base font-bold text-slate-900 dark:text-slate-100">{usd(val)}</div>
                </div>
              ))}
            </div>

            <div className="mt-4 grid gap-3 md:grid-cols-2">
              <div className="rounded-xl border border-slate-200 p-3 dark:border-slate-700">
                <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100">Invoices</h3>
                {(detail.invoices || []).length === 0 && <div className="mt-1 text-xs text-slate-400">None</div>}
                {(detail.invoices || []).map((i) => (
                  <div key={i.id} className="mt-1 flex justify-between text-sm">
                    <span>{i.invoice_number} <span className="text-xs text-slate-400">({i.status})</span></span>
                    <span>{usd(i.balance_due)} due</span>
                  </div>
                ))}
              </div>
              <div className="rounded-xl border border-slate-200 p-3 dark:border-slate-700">
                <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100">Purchase Orders</h3>
                {(detail.purchase_orders || []).length === 0 && <div className="mt-1 text-xs text-slate-400">None</div>}
                {(detail.purchase_orders || []).map((p) => (
                  <div key={p.id} className="mt-1 flex justify-between text-sm">
                    <span>{p.po_number} · {p.vendor_name} <span className="text-xs text-slate-400">({p.status})</span></span>
