            </div>
          </div>
        )}
      </div>
    </details>
  );
}

import { useMemo, useRef, useState } from "react";
import { AlertTriangle, Loader2, MapPin, X } from "lucide-react";
import { TENDER_BUCKETS, BUCKET_LABELS, batchTotals, computeVariance, nextBatchNumber } from "./reconciliationModel";
import { NotificationTriggers } from "@/components/workflow/NotificationService";

const clean = (v) => String(v ?? "").trim();
const usd = (n) => `$${Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const inputCls = "min-h-10 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 focus:border-violet-400 focus:outline-none dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100";
const labelCls = "mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400";

// "New Reconciliation" wizard: lists every unreconciled payment grouped by
// tender bucket with expected totals, takes counted amounts plus an optional
// cash adjustment, and closes the batch through manageReconciliation.
export default function ReconcileWizard({ sessionToken, payments, batches, locations, salesLocations = [], invoke, onClose, onClosed }) {
  const expected = useMemo(() => batchTotals(payments), [payments]);
  const previewNumber = useMemo(() => nextBatchNumber(batches), [batches]);
  const [counted, setCounted] = useState(() => Object.fromEntries(TENDER_BUCKETS.map((b) => [b, ""])));
  // The batch location comes from the SalesLocation registry now (stored on
  // the batch as the location name, same as the free-text days). Legacy
  // locations that never became registry rows stay selectable below.
  const locationOptions = useMemo(() => {
    const opts = [];
    const seen = new Set();
    for (const loc of salesLocations || []) {
      const name = clean(loc?.name);
      if (!name || loc?.active === false || seen.has(name.toLowerCase())) continue;
      seen.add(name.toLowerCase());
      const code = clean(loc?.code);
      opts.push({ value: name, label: code ? `${name} (${code})` : name });
    }
    for (const loc of locations || []) {
      const name = clean(loc);
      if (!name || seen.has(name.toLowerCase())) continue;
      seen.add(name.toLowerCase());
      opts.push({ value: name, label: name });
    }
    return opts;
  }, [salesLocations, locations]);
  const [location, setLocation] = useState(() => clean(locationOptions[0]?.value));
  const [adjustment, setAdjustment] = useState("");
  const [adjustmentNote, setAdjustmentNote] = useState("");
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const keyRef = useRef(crypto.randomUUID());

  const countedTotal = TENDER_BUCKETS.reduce((s, b) => s + (Number(counted[b]) || 0), 0);
  const adj = Number(adjustment) || 0;
  const variance = computeVariance(expected.total, countedTotal || expected.total, adj);
  const countedBlank = TENDER_BUCKETS.every((b) => !clean(counted[b]));

  const grouped = useMemo(() => {
    const out = Object.fromEntries(TENDER_BUCKETS.map((b) => [b, []]));
    for (const p of payments || []) out[p.bucket || "other"]?.push(p);
    return out;
  }, [payments]);

  const submit = async () => {
    if (saving) return;
    if (adj !== 0 && !clean(adjustmentNote)) { setError("Explain the cash adjustment."); return; }
    setSaving(true);
    setError("");
    try {
      const data = await invoke(sessionToken, {
        action: "create_batch",
        creation_request_key: keyRef.current,
        location: clean(location),
        counted: Object.fromEntries(TENDER_BUCKETS.map((b) => [b, Number(counted[b]) || 0])),
        cash_adjustment: adj,
        adjustment_note: clean(adjustmentNote),
        notes: clean(notes),
      });
      // Unified alerts: closing with a non-zero variance emits recon_variance —
      // fire-and-forget, it never blocks the batch close.
      try {
        const batchVariance = Number(data?.batch?.variance);
        const resolvedVariance = Number.isFinite(batchVariance) ? batchVariance : variance;
        if (data?.batch?.id && Math.abs(resolvedVariance) >= 0.005) {
          void NotificationTriggers.reconVariance(data.batch, { variance: resolvedVariance });
        }
      } catch { /* notify is best-effort */ }
      onClosed?.(data);
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || "The batch could not be closed.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-950/50 p-4" onClick={onClose}>
      <div className="my-8 w-full max-w-3xl rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-700 dark:bg-slate-900" onClick={(e) => e.stopPropagation()}>
        <div className="mb-4 flex items-center justify-between">
          <div>
            <h2 className="text-lg font-bold text-slate-900 dark:text-slate-100">New Reconciliation — {previewNumber}</h2>
            <p className="text-xs text-slate-500 dark:text-slate-400">{expected.count} recorded payment{expected.count === 1 ? "" : "s"} since the last close.</p>
          </div>
          <button onClick={onClose} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-slate-800"><X className="h-5 w-5" /></button>
        </div>

        <div className="grid gap-4 md:grid-cols-2">
          <div>
            <label className={labelCls}>Location</label>
            <div className="relative">
              <MapPin className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <select className={`${inputCls} pl-9`} value={location} onChange={(e) => setLocation(e.target.value)}>
                {locationOptions.length === 0 && <option value="">No locations -- add one in the Locations panel</option>}
                {locationOptions.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
              </select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className={labelCls}>Cash adjustment $</label>
              <input className={inputCls} type="number" step="0.01" value={adjustment} onChange={(e) => setAdjustment(e.target.value)} placeholder="0.00" />
            </div>
            <div>
              <label className={labelCls}>Adjustment note{adj !== 0 ? " *" : ""}</label>
              <input className={inputCls} value={adjustmentNote} onChange={(e) => setAdjustmentNote(e.target.value)} placeholder="Till over/short reason" />
            </div>
          </div>
        </div>

        <div className="mt-4 overflow-hidden rounded-xl border border-slate-200 dark:border-slate-700">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-xs font-semibold uppercase text-slate-500 dark:bg-slate-800 dark:text-slate-400">
              <tr>
                <th className="px-4 py-2">Tender</th>
                <th className="px-4 py-2 text-right">Payments</th>
                <th className="px-4 py-2 text-right">Expected</th>
                <th className="px-4 py-2 text-right">Counted</th>
                <th className="px-4 py-2 text-right">Variance</th>
              </tr>
            </thead>
            <tbody>
              {TENDER_BUCKETS.map((b) => {
                const exp = expected[b] || 0;
                const countedVal = counted[b] === "" ? exp : Number(counted[b]) || 0;
                const v = computeVariance(exp, countedVal, b === "cash" ? adj : 0);
                return (
                  <tr key={b} className="border-t border-slate-100 dark:border-slate-800">
                    <td className="px-4 py-2 font-semibold text-slate-800 dark:text-slate-200">{BUCKET_LABELS[b]}</td>
                    <td className="px-4 py-2 text-right text-slate-500">{grouped[b].length}</td>
                    <td className="px-4 py-2 text-right">{usd(exp)}</td>
                    <td className="px-4 py-2 text-right">
                      <input className="w-28 rounded-lg border border-slate-300 bg-white px-2 py-1 text-right text-sm dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100"
                        type="number" step="0.01" min="0" placeholder={exp.toFixed(2)} value={counted[b]}
                        onChange={(e) => setCounted((c) => ({ ...c, [b]: e.target.value }))} />
                    </td>
                    <td className={`px-4 py-2 text-right font-semibold ${Math.abs(v) < 0.005 ? "text-emerald-600" : "text-amber-600"}`}>{usd(v)}</td>
                  </tr>
                );
              })}
              <tr className="border-t-2 border-slate-200 bg-slate-50 font-bold dark:border-slate-700 dark:bg-slate-800/60">
                <td className="px-4 py-2 text-slate-900 dark:text-slate-100">Total</td>
                <td className="px-4 py-2 text-right">{expected.count}</td>
                <td className="px-4 py-2 text-right">{usd(expected.total)}</td>
                <td className="px-4 py-2 text-right">{usd(countedBlank ? expected.total : countedTotal)}</td>
                <td className={`px-4 py-2 text-right ${Math.abs(variance) < 0.005 ? "text-emerald-600" : "text-amber-600"}`}>{usd(variance)}</td>
              </tr>
            </tbody>
          </table>
        </div>
        <p className="mt-1.5 text-[11px] text-slate-500 dark:text-slate-400">Blank counted fields default to the expected amount. The cash adjustment is applied to the cash line.</p>

        <details className="mt-3">
          <summary className="cursor-pointer text-xs font-semibold text-slate-500 dark:text-slate-400">Payments in this close ({payments?.length || 0})</summary>
          <div className="mt-2 max-h-48 overflow-y-auto rounded-xl border border-slate-200 dark:border-slate-700">
            <table className="w-full text-xs">
              <tbody>
                {(payments || []).map((p) => (
                  <tr key={p.id} className="border-t border-slate-100 first:border-t-0 dark:border-slate-800">
                    <td className="px-3 py-1.5 text-slate-500">{p.paid_date || "—"}</td>
                    <td className="px-3 py-1.5 font-medium text-slate-800 dark:text-slate-200">{p.invoice_number || p.invoice_id || "—"}</td>
                    <td className="px-3 py-1.5 text-slate-600 dark:text-slate-300">{p.customer_display_name || "—"}</td>
                    <td className="px-3 py-1.5 text-slate-500">{BUCKET_LABELS[p.bucket] || p.method}</td>
                    <td className="px-3 py-1.5 text-right font-semibold">{usd(p.amount)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>

        <div className="mt-3">
          <label className={labelCls}>Batch notes</label>
          <textarea className={`${inputCls} min-h-14`} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Deposit bag #, drawer, anything the next closer should know…" />
        </div>

        {Math.abs(variance) >= 0.005 && (
          <div className="mt-3 flex items-start gap-2 rounded-xl bg-amber-50 px-3 py-2 text-sm font-medium text-amber-800 dark:bg-amber-950/40 dark:text-amber-200">
            <AlertTriangle className="mt-0.5 h-4 w-4 flex-shrink-0" />
            This close is {variance > 0 ? "over" : "short"} by {usd(Math.abs(variance))}. Double-check the counted amounts before closing.
          </div>
        )}
        {error && <div className="mt-3 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</div>}

        <div className="mt-4 flex justify-end gap-2">
          <button onClick={onClose} className="min-h-10 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-600 dark:border-slate-600 dark:text-slate-300">Cancel</button>
          <button onClick={submit} disabled={saving || expected.count === 0}
            className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white hover:bg-violet-700 disabled:opacity-60">
            {saving && <Loader2 className="h-4 w-4 animate-spin" />}
            Close batch {previewNumber}
          </button>
        </div>
      </div>
    </div>
  );
}

// Pure helpers for the Reconciliation (batched cash close) module.
// The Payment.method enum is cash|check|card|ach|financing|other; the close
// counts four CoreBridge-style tender buckets — cash, check, card, and other,
// where "other" absorbs ach/financing/unknown methods.

export const TENDER_BUCKETS = ["cash", "check", "card", "other"];

export const BUCKET_LABELS = { cash: "Cash", check: "Check", card: "Card", other: "Other" };

export const bucketFor = (method) => {
  const m = String(method ?? "").trim().toLowerCase();
  return TENDER_BUCKETS.includes(m) ? m : "other";
};

const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const money = (v) => Math.round(v * 100) / 100;

// Payments still waiting to be swept into a close: recorded (not void/
// refunded), carrying no reconciliation_batch_id, and not already listed in
// any batch's payment_ids (defends against rows whose back-link was never set).
export function unreconciledPayments(payments = [], batches = []) {
  const swept = new Set();
  for (const b of Array.isArray(batches) ? batches : []) {
    for (const id of Array.isArray(b?.payment_ids) ? b.payment_ids : []) {
      const key = String(id ?? "").trim();
      if (key) swept.add(key);
    }
  }
  return (Array.isArray(payments) ? payments : []).filter((p) => {
    if (!p || typeof p !== "object") return false;
    if (String(p.status ?? "recorded") !== "recorded") return false;
    if (String(p.reconciliation_batch_id ?? "").trim()) return false;
    return !swept.has(String(p.id ?? "").trim());
  });
}

// Expected totals for a close, grouped by tender bucket.
// Returns { cash, check, card, other, total, count, by_method } where by_method
// keeps the raw per-method sums for audit detail.
export function batchTotals(payments = []) {
  const buckets = { cash: 0, check: 0, card: 0, other: 0 };
  const byMethod = {};
  let count = 0;
  for (const p of Array.isArray(payments) ? payments : []) {
    if (!p || String(p.status ?? "recorded") !== "recorded") continue;
    const amount = num(p.amount);
    const method = String(p.method ?? "other").trim().toLowerCase() || "other";
    buckets[bucketFor(method)] = money(buckets[bucketFor(method)] + amount);
    byMethod[method] = money((byMethod[method] || 0) + amount);
    count += 1;
  }
  const total = money(TENDER_BUCKETS.reduce((s, b) => s + buckets[b], 0));
  return { ...buckets, total, count, by_method: byMethod };
}

// counted + cashAdjustment - expected. Positive = over, negative = short.
export function computeVariance(expected, collected, adjustment = 0) {
  return money(num(collected) + num(adjustment) - num(expected));
}

// Next REC-#### number: one past the highest numeric suffix already issued.
// Batch numbers are allocated server-side via DocNumberCounter; this is the
// client-side preview and the fallback for display-only contexts.
export function nextBatchNumber(batches = []) {
  let max = 0;
  for (const b of Array.isArray(batches) ? batches : []) {
    const m = /^REC-(\d+)$/i.exec(String(b?.batch_number ?? "").trim());
    if (m) max = Math.max(max, parseInt(m[1], 10));
  }
  return `REC-${String(max + 1).padStart(4, "0")}`;
}

import { useEffect, useMemo, useState } from "react";
import { base44 } from "@/api/base44Client";
import { CheckCircle2, ClipboardCopy, Loader2, Mail, MailCheck, Truck } from "lucide-react";
import { sendStaffEmail } from "@/components/comms/sendStaffEmail";
import {
  LINE_STATUS_LABELS,
  buildReceiptLines,
  derivePoReceipt,
  receivingSummaryText,
  vendorNotifyMailto,
} from "./receivingModel";

const clean = (v) => String(v ?? "").trim();
const usd = (n) => `$${Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const LINE_BADGE_STYLES = {
  open: "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300",
  partial: "bg-amber-100 text-amber-700 dark:bg-amber-900/60 dark:text-amber-300",
  received: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/60 dark:text-emerald-300",
};

function LineStatusBadge({ status }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${LINE_BADGE_STYLES[status] || LINE_BADGE_STYLES.open}`}>
      {LINE_STATUS_LABELS[status] || status}
    </span>
  );
}

// Receiving history for stock-linked lines is stored as InventoryMovement rows
// (reason "receive", note "Received on <po_number>"). Non-stock lines have no
// per-event history — the entity only keeps cumulative quantity_received.
function useReceiveHistory(sessionToken, po) {
  const [rows, setRows] = useState([]);
  const [failed, setFailed] = useState(false);
  const poNumber = clean(po?.po_number);
  const hasStockLink = (po?.line_items || []).some((l) => clean(l?.inventory_item_id));
  useEffect(() => {
    if (!sessionToken || !poNumber || !hasStockLink) { setRows([]); return; }
    let live = true;
    base44.functions.invoke("inventoryAction", { session_token: sessionToken, action: "list_movements" })
      .then((r) => {
        if (!live) return;
        const d = r?.data || r;
        if (!d?.success) { setFailed(true); return; }
        setRows((d.movements || [])
          .filter((m) => clean(m?.reason) === "receive" && clean(m?.note).includes(poNumber))
          .sort((a, b) => clean(b?.created_date).localeCompare(clean(a?.created_date))));
      })
      .catch(() => { if (live) setFailed(true); });
    return () => { live = false; };
  }, [sessionToken, poNumber, hasStockLink]);
  return { rows, failed, hasStockLink };
}

// Per-PO receiving panel: per-line status + backorder tracking + receive inputs
// that call the existing purchaseOrderAction receive_items action via the
// parent's onReceive callback (payload: [{index, quantity}]).
export default function ReceivePanel({ po, sessionToken, canReceive, busy, onReceive }) {
  const [receiveQtys, setReceiveQtys] = useState({});
  const [localError, setLocalError] = useState("");
  const [copied, setCopied] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [emailState, setEmailState] = useState({ status: "idle", error: "" });
  const receipt = useMemo(() => derivePoReceipt(po), [po]);
  const history = useReceiveHistory(sessionToken, po);

  const submit = () => {
    const { lines, errors } = buildReceiptLines(receiveQtys, receipt);
    if (errors.length > 0) { setLocalError(errors.join(" ")); return; }
    setLocalError("");
    onReceive?.(lines);
    setReceiveQtys({});
  };

  const fillAll = () => setReceiveQtys(
    Object.fromEntries(receipt.lines.filter((l) => l.open > 0).map((l) => [l.index, l.open])),
  );

  const mailto = vendorNotifyMailto(po, receipt);
  const vendorEmail = clean(po?.vendor_email); // same field the mailto path uses
  const poNumber = clean(po?.po_number) || "(no number)";

  // Bridge send path — the same plain-text summary the clipboard copy uses.
  // The mailto stays as the fallback: when no vendor_email is on file it opens
  // the mail app with subject/body prefilled for the operator to address.
  const sendVendorEmail = async () => {
    if (!vendorEmail || emailState.status === "sending" || emailState.status === "sent") return;
    setEmailState({ status: "sending", error: "" });
    try {
      await sendStaffEmail({
        sessionToken,
        to: vendorEmail,
        subject: `PO ${poNumber} — receipt/backorder notice`,
        body: receivingSummaryText(po, receipt),
        kind: "po_vendor_notify",
        // Vendor replies route to the buyer on record (po.created_by holds the
        // creator's staff email); a non-email value falls back to the default.
        replyTo: clean(po?.created_by).includes("@") ? clean(po?.created_by) : undefined,
      });
      setEmailState({ status: "sent", error: "" });
    } catch (e) {
      setEmailState({ status: "failed", error: e?.message || "Email could not be sent." });
    }
  };

  const copySummary = async () => {
    try {
      await navigator.clipboard.writeText(receivingSummaryText(po, receipt));
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch { /* clipboard unavailable */ }
  };

  return (
    <div>
      {/* Rollup progress strip */}
      <div className="mb-2 flex items-center gap-3">
        <div className="h-2 flex-1 overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
          <div
            className={`h-full rounded-full transition-all ${receipt.complete ? "bg-emerald-500" : "bg-amber-500"}`}
            style={{ width: `${receipt.percent_received}%` }}
          />
        </div>
        <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">
          {receipt.percent_received}% received
          {receipt.totals.backordered > 0 && (
            <span className="ml-2 rounded-full bg-red-100 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-red-700 dark:bg-red-950/60 dark:text-red-300">
              Backorder {receipt.totals.backordered}
            </span>
          )}
          {receipt.overdue && (
            <span className="ml-2 rounded-full bg-red-100 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-red-700 dark:bg-red-950/60 dark:text-red-300">Overdue</span>
          )}
        </span>
      </div>

      <div className="overflow-x-auto rounded-xl border border-slate-200 dark:border-slate-700">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-left text-xs font-semibold uppercase text-slate-500 dark:bg-slate-800 dark:text-slate-400">
            <tr>
              <th className="px-3 py-2">Item</th>
              <th className="px-3 py-2 text-right">Ordered</th>
              <th className="px-3 py-2 text-right">Received</th>
              <th className="px-3 py-2 text-right">Open / BO</th>
              <th className="px-3 py-2 text-right">Cost</th>
              <th className="px-3 py-2 text-right">Total</th>
              <th className="px-3 py-2">Status</th>
              {canReceive && (
                <th className="px-3 py-2 text-right">
                  Receive qty
                  <button type="button" title="Fill every line with its full open quantity" onClick={fillAll}
                    className="ml-1.5 rounded bg-emerald-100 px-1.5 py-0.5 text-[10px] font-bold normal-case text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-900/60 dark:text-emerald-300">ALL</button>
                </th>
              )}
            </tr>
          </thead>
          <tbody>
            {receipt.lines.map((l) => (
              <tr key={l.index} className="border-t border-slate-100 dark:border-slate-800">
                <td className="px-3 py-2 text-slate-800 dark:text-slate-100">
                  {l.description}
                  {l.inventory_item_id && <span className="ml-1.5 text-[10px] font-semibold uppercase tracking-wide text-violet-500" title="Linked to an inventory stock item — receiving posts stock">stock</span>}
                </td>
                <td className="px-3 py-2 text-right">{l.ordered}</td>
                <td className="px-3 py-2 text-right">{l.received}</td>
                <td className="px-3 py-2 text-right">
                  {l.open}
                  {l.backordered > 0 && (
                    <span className="ml-1 rounded bg-red-100 px-1 py-0.5 text-[10px] font-bold text-red-700 dark:bg-red-950/60 dark:text-red-300" title="Vendor backorder — still owed after a receipt">
                      BO {l.backordered}
                    </span>
                  )}
                </td>
                <td className="px-3 py-2 text-right">{usd(l.unit_cost)}</td>
                <td className="px-3 py-2 text-right font-medium">
                  {usd(l.ordered_cost)}
                  {l.variance_cost !== 0 && (
                    <div className={`text-[10px] font-semibold ${l.variance_cost < 0 ? "text-amber-600" : "text-emerald-600"}`}>
                      {l.variance_cost < 0 ? "-" : "+"}{usd(Math.abs(l.variance_cost))} recv
                    </div>
                  )}
                </td>
                <td className="px-3 py-2"><LineStatusBadge status={l.status} /></td>
                {canReceive && (
                  <td className="px-3 py-2 text-right">
                    {l.open > 0 ? (
                      <input className="w-20 rounded-lg border border-slate-300 px-2 py-1 text-right text-sm dark:border-slate-600 dark:bg-slate-800"
                        type="number" min="0" max={l.open} step="any" placeholder={String(l.open)}
                        value={receiveQtys[l.index] ?? ""}
                        onChange={(e) => setReceiveQtys((s) => ({ ...s, [l.index]: e.target.value }))} />
                    ) : <CheckCircle2 className="ml-auto h-4 w-4 text-emerald-500" />}
                  </td>
                )}
              </tr>
            ))}
            {receipt.lines.length === 0 && (
              <tr><td colSpan={8} className="px-3 py-4 text-center text-slate-400">No line items.</td></tr>
            )}
          </tbody>
          {receipt.lines.length > 0 && (
            <tfoot className="border-t border-slate-200 bg-slate-50 text-xs font-semibold text-slate-600 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300">
              <tr>
                <td className="px-3 py-2">Totals</td>
                <td className="px-3 py-2 text-right">{receipt.totals.ordered}</td>
                <td className="px-3 py-2 text-right">{receipt.totals.received}</td>
                <td className="px-3 py-2 text-right">{receipt.totals.open}{receipt.totals.backordered > 0 ? ` (BO ${receipt.totals.backordered})` : ""}</td>
                <td className="px-3 py-2" />
                <td className="px-3 py-2 text-right">{usd(receipt.totals.ordered_cost)}</td>
                <td className="px-3 py-2" colSpan={canReceive ? 2 : 1} />
              </tr>
            </tfoot>
          )}
        </table>
      </div>

      {localError && <div className="mt-2 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">{localError}</div>}

      <div className="mt-3 flex flex-wrap items-center gap-2">
        {canReceive && (
          <button type="button" onClick={submit} disabled={Boolean(busy)}
            className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-emerald-600 px-4 text-sm font-semibold text-white hover:bg-emerald-700 disabled:opacity-60">
            {busy === "receive" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Truck className="h-4 w-4" />}Record receipt
          </button>
        )}
        {/* Vendor notify: primary path sends through the sendStaffEmail bridge
            when the PO carries a vendor_email; the mailto link remains as the
            fallback (always rendered until a send succeeds — with no
            vendor_email it opens the mail app for manual addressing). */}
        {vendorEmail && (
          <button type="button" onClick={sendVendorEmail}
            disabled={Boolean(busy) || emailState.status === "sending" || emailState.status === "sent"}
            className="inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-sky-600 px-4 text-sm font-semibold text-white hover:bg-sky-700 disabled:opacity-60">
            {emailState.status === "sending"
              ? <Loader2 className="h-4 w-4 animate-spin" />
              : emailState.status === "sent" ? <MailCheck className="h-4 w-4" /> : <Mail className="h-4 w-4" />}
            {emailState.status === "sending" ? "Sending…" : emailState.status === "sent" ? "Email sent" : "Email vendor"}
          </button>
        )}
        {emailState.status !== "sent" && (
          <a href={mailto.href}
            className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-600 hover:bg-slate-50 dark:border-slate-600 dark:text-slate-300 dark:hover:bg-slate-800">
            <Mail className="h-4 w-4" />{vendorEmail ? "Open in mail app" : "Email vendor"}
          </a>
        )}
        {emailState.status === "sent" && (
          <span className="self-center text-xs font-semibold text-emerald-600 dark:text-emerald-400">Sent to {vendorEmail}</span>
        )}
        <button type="button" onClick={copySummary}
          className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-600 hover:bg-slate-50 dark:border-slate-600 dark:text-slate-300 dark:hover:bg-slate-800">
          <ClipboardCopy className="h-4 w-4" />{copied ? "Copied" : "Copy summary"}
        </button>
        {history.hasStockLink && (
          <button type="button" onClick={() => setShowHistory((s) => !s)}
            className="min-h-10 rounded-xl px-3 text-xs font-semibold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200">
            {showHistory ? "Hide receipt history" : `Receipt history (${history.rows.length})`}
          </button>
        )}
      </div>

      {emailState.status === "failed" && (
        <div className="mt-2 rounded-xl bg-red-50 px-3 py-2 text-sm font-medium text-red-700 dark:bg-red-950/40 dark:text-red-300">
          Vendor email failed: {emailState.error} Use “Open in mail app” to send it manually.
        </div>
      )}

      {showHistory && (
        <div className="mt-2 rounded-xl border border-slate-200 p-3 dark:border-slate-700">
          <h4 className="text-xs font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400">Stock receipts on this PO</h4>
          {history.rows.length === 0 ? (
            <div className="mt-1 text-xs text-slate-400">
              {history.failed ? "History unavailable." : "No stock receipts recorded yet — only stock-linked lines post history."}
            </div>
          ) : (
            history.rows.map((m) => (
              <div key={m.id} className="mt-1 flex justify-between text-xs text-slate-600 dark:text-slate-300">
                <span>{m.item_label || m.item_id} <span className="text-slate-400">({clean(m.created_date).slice(0, 10)}{m.created_by ? ` · ${m.created_by}` : ""})</span></span>
                <span className="font-semibold text-emerald-600">+{Math.abs(Number(m.delta) || 0)}</span>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Loader2, Printer, X } from "lucide-react";
import { derivePoReceipt } from "./receivingModel";

const clean = (v) => String(v ?? "").trim();
const usd = (n) => `$${Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

// Same print approach as components/statements/StatementView.jsx: a
// stmt-print-root overlay + a body class that hides the app shell under
// @media print; window.print() produces the paper/PDF copy.
const VENDOR_STATEMENT_PRINT_CSS = `
@media print {
  body.stmt-printing * { visibility: hidden !important; }
  body.stmt-printing .stmt-print-root,
  body.stmt-printing .stmt-print-root * { visibility: visible !important; }
  .stmt-print-root { position: static !important; overflow: visible !important; }
  .stmt-print-root .stmt-toolbar, .stmt-print-root .stmt-no-print { display: none !important; }
  nav, .top-nav, .side-nav, [data-shell-navigation-handle] { display: none !important; }
}
.stmt-sheet { page-break-after: always; break-after: page; }
.stmt-sheet:last-child { page-break-after: auto; break-after: auto; }
`;

const STATUS_LABELS = {
  draft: "Draft",
  sent: "Sent",
  partially_received: "Partial",
  received: "Received",
  cancelled: "Cancelled",
};

const invokeAction = async (sessionToken, body) => {
  const r = await base44.functions.invoke("purchaseOrderAction", { session_token: sessionToken, ...body });
  const data = r?.data || r;
  if (!data?.success) throw new Error(data?.error || "Request failed.");
  return data;
};

// list_purchase_orders returns header snapshots only — expected-vs-received
// line detail ships on get_purchase_order. Open/detail fetches are capped and
// fetched in small batches, same as OpsReportView's Parts Needed load.
const DETAIL_CAP = 40;
const DETAIL_BATCH = 5;

/**
 * VendorStatement — per-vendor aggregated account view: every PO on the
 * vendor, open expected-vs-received quantities/costs, status rollup and
 * totals, rendered as a printable sheet (window.print pattern).
 */
export default function VendorStatement({ sessionToken, vendorName, onClose }) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [pos, setPos] = useState([]);
  const [capped, setCapped] = useState(false);

  useEffect(() => {
    document.body.classList.add("stmt-printing");
    return () => document.body.classList.remove("stmt-printing");
  }, []);

  const vendor = clean(vendorName);

  useEffect(() => {
    let live = true;
    if (!sessionToken || !vendor) { setLoading(false); return; }
    setLoading(true);
    setError("");
    (async () => {
      const listed = await invokeAction(sessionToken, { action: "list_purchase_orders", query: vendor });
      const all = Array.isArray(listed?.purchase_orders) ? listed.purchase_orders : [];
      // The list action searches PO # + vendor text; narrow to this vendor
      // client-side (exact normalized match first, prefix/contains fallback).
      const nk = (v) => clean(v).toLowerCase();
      let mine = all.filter((p) => nk(p?.vendor_name) === nk(vendor));
      if (!mine.length) mine = all.filter((p) => nk(p?.vendor_name).includes(nk(vendor)) || nk(vendor).includes(nk(p?.vendor_name)));
      const trimmed = mine.slice(0, DETAIL_CAP);
      const out = [];
      for (let i = 0; i < trimmed.length; i += DETAIL_BATCH) {
        // eslint-disable-next-line no-await-in-loop -- intentional small batches
        const chunk = await Promise.all(trimmed.slice(i, i + DETAIL_BATCH).map((p) =>
          invokeAction(sessionToken, { action: "get_purchase_order", purchase_order_id: p.id })
            .then((d) => d?.purchase_order || null)
            .catch(() => null)));
        out.push(...chunk.filter(Boolean));
      }
      if (live) { setPos(out); setCapped(mine.length > DETAIL_CAP || all.length > trimmed.length); }
    })()
      .catch((e) => { if (live) setError(e?.response?.data?.error || e?.message || "Vendor statement could not be loaded."); })
      .finally(() => { if (live) setLoading(false); });
    return () => { live = false; };
  }, [sessionToken, vendor]);

  const statement = useMemo(() => {
    const rows = pos.map((po) => ({ po, receipt: derivePoReceipt(po) }));
    rows.sort((a, b) => clean(b.po?.order_date || b.po?.created_date).localeCompare(clean(a.po?.order_date || a.po?.created_date)));
    const byStatus = {};
    const totals = { ordered: 0, received: 0, open: 0, backordered: 0, ordered_cost: 0, received_cost: 0, open_cost: 0, po_total: 0, paid: 0 };
    for (const { po, receipt } of rows) {
      const s = clean(po?.status) || "draft";
      byStatus[s] = (byStatus[s] || 0) + 1;
      totals.ordered += receipt.totals.ordered;
      totals.received += receipt.totals.received;
      totals.open += receipt.totals.open;
      totals.backordered += receipt.totals.backordered;
      totals.ordered_cost += receipt.totals.ordered_cost;
      totals.received_cost += receipt.totals.received_cost;
      totals.open_cost += receipt.totals.open_cost;
      totals.po_total += Number(po?.total) || 0;
      totals.paid += Number(po?.paid_amount) || 0;
    }
    const contact = pos.find((p) => clean(p?.vendor_contact) || clean(p?.vendor_email) || clean(p?.vendor_phone)) || {};
    const openCount = rows.filter(({ po }) => ["sent", "partially_received"].includes(clean(po?.status))).length;
    return { rows, byStatus, totals, openCount, contact };
  }, [pos]);

  const asOf = new Date().toISOString().slice(0, 10);
  const pctReceived = statement.totals.ordered > 0
    ? Math.min(100, Math.round((statement.totals.received / statement.totals.ordered) * 1000) / 10)
    : 0;

  return (
    <div className="stmt-print-root fixed inset-0 z-[90] overflow-y-auto bg-slate-100">
      <style>{VENDOR_STATEMENT_PRINT_CSS}</style>
      <div className="stmt-toolbar sticky top-0 z-10 flex items-center gap-2 border-b bg-white p-3 shadow-sm">
        <Button type="button" size="sm" onClick={() => window.print()} className="gap-1.5">
          <Printer className="h-4 w-4" /> Print
        </Button>
        <Button type="button" size="sm" variant="ghost" onClick={onClose} className="gap-1.5">
          <X className="h-4 w-4" /> Close
        </Button>
        <span className="ml-2 text-xs text-slate-400">Vendor statement — {vendor || "vendor"}</span>
      </div>

      <div className="py-6">
        <div className="stmt-sheet mx-auto max-w-3xl bg-white p-6 text-slate-900 shadow-sm">
          <header className="mb-5 flex items-start justify-between gap-4 border-b-2 border-slate-800 pb-4">
            <div>
              <h1 className="text-xl font-bold leading-tight">Vendor statement</h1>
              <p className="mt-1 text-base font-semibold">{vendor || "—"}</p>
              <div className="mt-1 space-y-0.5 text-xs text-slate-500">
                {clean(statement.contact?.vendor_contact) && <p>{statement.contact.vendor_contact}</p>}
                {clean(statement.contact?.vendor_email) && <p>{statement.contact.vendor_email}</p>}
                {clean(statement.contact?.vendor_phone) && <p>{statement.contact.vendor_phone}</p>}
              </div>
            </div>
            <div className="shrink-0 text-right text-sm text-slate-600">
              <p>As of <span className="font-semibold">{asOf}</span></p>
              <p className="mt-1">{statement.rows.length} purchase order{statement.rows.length === 1 ? "" : "s"}</p>
            </div>
          </header>

          {loading ? (
            <div className="flex items-center justify-center py-14 text-slate-500">
              <Loader2 className="mr-2 h-5 w-5 animate-spin" />Loading vendor history…
            </div>
          ) : error ? (
            <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</div>
          ) : statement.rows.length === 0 ? (
            <p className="py-10 text-center text-sm text-slate-400">No purchase orders found for {vendor || "this vendor"}.</p>
          ) : (
            <>
              {/* Rollup strip */}
              <div className="mb-5 grid grid-cols-2 gap-2 sm:grid-cols-4">
                {[
                  ["POs on file", String(statement.rows.length)],
                  ["Open POs", String(statement.openCount)],
                  ["Ordered", usd(statement.totals.po_total)],
                  ["Received", `${pctReceived}%`],
                ].map(([label, val]) => (
                  <div key={label} className="rounded-lg border border-slate-300 p-2.5">
                    <div className="text-[10px] font-bold uppercase tracking-wider text-slate-500">{label}</div>
                    <div className="mt-0.5 text-sm font-bold text-slate-900">{val}</div>
                  </div>
                ))}
              </div>

              {/* POs by status */}
              <div className="mb-5 flex flex-wrap gap-1.5">
                {Object.entries(statement.byStatus).map(([s, count]) => (
                  <span key={s} className="rounded-full border border-slate-300 px-2.5 py-0.5 text-[11px] font-semibold text-slate-600">
                    {STATUS_LABELS[s] || s}: {count}
                  </span>
                ))}
              </div>

              {/* PO ledger */}
              <table className="w-full border-collapse text-sm">
                <thead>
                  <tr className="border-y-2 border-slate-800 text-left text-[10px] font-bold uppercase tracking-wider text-slate-500">
                    <th className="py-2 pr-2">PO</th>
                    <th className="py-2 pr-2">Ordered</th>
                    <th className="py-2 pr-2">Expected</th>
                    <th className="py-2 pr-2">Status</th>
                    <th className="py-2 pr-1 text-right">Ordered qty</th>
                    <th className="py-2 px-1 text-right">Received qty</th>
                    <th className="py-2 pl-1 text-right">Open / BO</th>
                    <th className="py-2 pl-2 text-right">PO total</th>
                  </tr>
                </thead>
                <tbody>
                  {statement.rows.map(({ po, receipt }) => {
                    const s = clean(po?.status) || "draft";
                    return (
                      <tr key={po.id} className="border-b border-slate-200 align-top">
                        <td className="py-1.5 pr-2 font-semibold text-slate-800">{clean(po?.po_number) || "PO"}</td>
                        <td className="py-1.5 pr-2 whitespace-nowrap text-slate-600">{clean(po?.order_date) || "—"}</td>
                        <td className="py-1.5 pr-2 whitespace-nowrap text-slate-600">
                          {clean(po?.expected_date) || "—"}
                          {receipt.overdue && <span className="ml-1 text-[10px] font-bold uppercase text-red-700">overdue</span>}
                        </td>
                        <td className="py-1.5 pr-2 text-slate-600">{STATUS_LABELS[s] || s}</td>
                        <td className="py-1.5 pr-1 text-right whitespace-nowrap">{receipt.totals.ordered}</td>
                        <td className="py-1.5 px-1 text-right whitespace-nowrap">{receipt.totals.received}</td>
                        <td className="py-1.5 pl-1 text-right whitespace-nowrap">
                          {receipt.totals.open}
                          {receipt.totals.backordered > 0 && <span className="ml-1 text-[10px] font-bold text-red-700">BO {receipt.totals.backordered}</span>}
                        </td>
                        <td className="py-1.5 pl-2 text-right whitespace-nowrap font-medium">{usd(po?.total)}</td>
                      </tr>
                    );
                  })}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 border-slate-800 text-sm font-bold">
                    <td className="py-2 pr-2" colSpan={4}>Totals</td>
                    <td className="py-2 pr-1 text-right">{statement.totals.ordered}</td>
                    <td className="py-2 px-1 text-right">{statement.totals.received}</td>
                    <td className="py-2 pl-1 text-right">{statement.totals.open}{statement.totals.backordered > 0 ? ` (BO ${statement.totals.backordered})` : ""}</td>
                    <td className="py-2 pl-2 text-right">{usd(statement.totals.po_total)}</td>
                  </tr>
                </tfoot>
              </table>

              {/* Cost rollup */}
              <div className="mt-3 flex justify-end">
                <table className="text-sm">
                  <tbody>
                    <tr><td className="pr-6 py-0.5 text-slate-500">Ordered cost</td><td className="py-0.5 text-right font-medium">{usd(statement.totals.ordered_cost)}</td></tr>
                    <tr><td className="pr-6 py-0.5 text-slate-500">Received cost</td><td className="py-0.5 text-right font-medium">{usd(statement.totals.received_cost)}</td></tr>
                    <tr><td className="pr-6 py-0.5 text-slate-500">Still to receive</td><td className="py-0.5 text-right font-medium">{usd(statement.totals.open_cost)}</td></tr>
                    {statement.totals.paid > 0 && (
                      <tr><td className="pr-6 py-0.5 text-slate-500">Paid to vendor</td><td className="py-0.5 text-right font-medium">{usd(statement.totals.paid)}</td></tr>
                    )}
                  </tbody>
                </table>
              </div>

              {capped && (
                <p className="stmt-no-print mt-3 text-[11px] text-amber-700">
                  Vendor history truncated at {DETAIL_CAP} purchase orders — narrow the vendor filter for a complete statement.
                </p>
              )}
              <p className="mt-6 text-center text-[10px] text-slate-400">
                Generated {asOf} · CCS Signage
              </p>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// Progress (milestone) billing math — pure and deterministic.
// CoreBridge-style AIA-lite: a job's contract value is split into percentage
// milestones; already-invoiced dollars walk the schedule in order, so the next
// billable milestone is always derivable from amounts alone. Hard caps: no
// milestone may push cumulative pct over 100 or billed dollars over job total.

const num = (v, fallback = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};
const clean = (v) => String(v ?? "").trim();
export const money = (v) => Math.round(num(v) * 100) / 100;
const EPS = 0.005;

export const MILESTONE_STATUS = { OPEN: "open", PARTIAL: "partial", BILLED: "billed" };
export const MILESTONE_STATUS_LABELS = { open: "Open", partial: "Partial", billed: "Billed" };

export const DEFAULT_SCHEDULE = [
  { label: "Deposit", pct: 50 },
  { label: "Completion", pct: 50 },
];

// Sanitize a user-entered schedule: trim labels, auto-label blanks, clamp pct to
// (0, 100], and trim the tail so cumulative pct never exceeds 100.
export function normalizeSchedule(schedule) {
  const rows = Array.isArray(schedule) ? schedule : [];
  const out = [];
  let cumulative = 0;
  rows.forEach((row, i) => {
    if (cumulative >= 100 - EPS) return;
    let pct = num(row?.pct, NaN);
    if (!Number.isFinite(pct) || pct <= 0) return;
    pct = Math.min(100, Math.round(pct * 100) / 100);
    if (cumulative + pct > 100 + EPS) pct = money(100 - cumulative);
    cumulative = money(cumulative + pct);
    const note = clean(row?.note);
    out.push({ label: clean(row?.label) || `Milestone ${out.length + 1}`, pct, ...(note ? { note } : {}) });
  });
  return out;
}

// Allocate dollar amounts onto a normalized schedule. Penny-safe: when the
// schedule totals 100%, the LAST milestone takes total minus prior cumulative
// so amounts always sum exactly to the job total.
export function milestoneAmounts(schedule, jobTotal) {
  const total = Math.max(0, money(jobTotal));
  const norm = normalizeSchedule(schedule);
  let cumulativePct = 0;
  let cumulativeAmount = 0;
  return norm.map((m, i) => {
    cumulativePct = money(cumulativePct + m.pct);
    // Penny-safe: each milestone gets (cumulative pct of total) minus what was
    // already allocated, so when the schedule reaches 100% the last milestone
    // takes the exact remainder and amounts sum exactly to the job total.
    const amount = money(money(total * (cumulativePct / 100)) - cumulativeAmount);
    cumulativeAmount = money(cumulativeAmount + amount);
    return { ...m, index: i, amount, cumulative_pct: cumulativePct, cumulative_amount: cumulativeAmount };
  });
}

// Billing state for one job: which milestones are covered by invoiced dollars,
// what the next billable milestone is, and the unscheduled remainder (when the
// schedule sums to less than 100%).
export function deriveBillingState({ jobTotal, schedule, invoiced } = {}) {
  const total = Math.max(0, money(jobTotal));
  const billed = Math.max(0, money(invoiced));
  const milestones = milestoneAmounts(schedule, total);
  const coveredTotal = Math.min(billed, total);
  let cursor = 0;
  const withStatus = milestones.map((m) => {
    const covered = Math.min(m.amount, Math.max(0, money(coveredTotal - cursor)));
    cursor = money(cursor + m.amount);
    const status = covered >= m.amount - EPS && m.amount > EPS
      ? MILESTONE_STATUS.BILLED
      : covered > EPS
        ? MILESTONE_STATUS.PARTIAL
        : MILESTONE_STATUS.OPEN;
    return { ...m, covered: money(covered), open_amount: money(m.amount - covered), status };
  });
  const scheduledAmount = milestones.length ? milestones[milestones.length - 1].cumulative_amount : 0;
  const scheduledPct = milestones.length ? milestones[milestones.length - 1].cumulative_pct : 0;
  const unscheduledAmount = money(total - scheduledAmount);

  const nextMilestone = withStatus.find((m) => m.status !== MILESTONE_STATUS.BILLED) || null;
  const remaining = money(total - billed);
  const next = nextMilestone && remaining > EPS
    ? {
        index: nextMilestone.index,
        label: nextMilestone.label,
        pct: nextMilestone.pct,
        amount: money(Math.min(nextMilestone.open_amount, remaining)),
        cumulative_pct_after: nextMilestone.cumulative_pct,
        is_final: nextMilestone.index === withStatus.length - 1 && unscheduledAmount <= EPS,
      }
    : null;

  return {
    job_total: total,
    invoiced: billed,
    collected_coverage: money(Math.min(billed, total)),
    billed_pct: total > EPS ? Math.round((coveredTotal / total) * 1000) / 10 : 0,
    remaining,
    over_billed: billed > total + EPS ? money(billed - total) : 0,
    milestones: withStatus,
    scheduled_pct: scheduledPct,
    unscheduled_pct: money(100 - scheduledPct),
    unscheduled_amount: unscheduledAmount,
    next,
    complete: remaining <= EPS && total > EPS,
  };
}

// Exact invoicingAction create_invoice payload for one milestone bill.
// Backend: {action:'create_invoice', creation_request_key, fields:{customer_id,
// work_order_id, estimate_id, opportunity_id, line_items:[{description,quantity,
// unit_price,taxable}], notes, source_summary}} — creates a DRAFT invoice.
export function buildMilestoneInvoicePayload({ workOrder, milestone, jobTotal, schedule, requestKey }) {
  const wo = workOrder || {};
  const title = clean(wo.title) || "Work order";
  const description = `${milestone.label} (${milestone.pct}%) — progress billing — ${title}`;
  return {
    action: "create_invoice",
    creation_request_key: clean(requestKey) || `progress-billing:${clean(wo.id)}:${milestone.index}:${Date.now()}`,
    fields: {
      customer_id: clean(wo.customer_id),
      customer_display_name: clean(wo.client_name),
      work_order_id: clean(wo.id),
      estimate_id: clean(wo.estimate_id),
      opportunity_id: clean(wo.opportunity_id),
      line_items: [{ description, quantity: 1, unit_price: money(milestone.amount), taxable: false }],
      notes: `Progress billing milestone "${milestone.label}" — ${milestone.pct}% of ${money(jobTotal)} contract value.`,
      source_summary: {
        kind: "progress_billing",
        milestone_index: milestone.index,
        milestone_label: milestone.label,
        milestone_pct: milestone.pct,
        job_total: money(jobTotal),
        schedule: normalizeSchedule(schedule),
      },
    },
  };
}

// Fallback payload when the work order has no customer_id but does link an
// approved estimate — routes through invoicingAction create_from_estimate,
// which enforces its own remaining-billable cap server-side.
// Backend: {action:'create_from_estimate', estimate_id, billing_mode,
// deposit_amount, notes}.
export function buildEstimateBillingPayload({ estimateId, milestone, isFinal }) {
  return {
    action: "create_from_estimate",
    estimate_id: clean(estimateId),
    billing_mode: isFinal ? "final" : "deposit",
    ...(isFinal ? {} : { deposit_amount: money(milestone.amount) }),
    notes: `Progress billing milestone "${milestone.label}" (${milestone.pct}%).`,
  };
}

// WorkOrder.billing_schedule round trip. The entity field stores normalized
// {label, pct, note} rows — scheduleToEntity clamps pct > 0, caps cumulative
// at 100 and drops junk rows before write; scheduleFromEntity re-normalizes
// on read so malformed or legacy rows never reach the UI. An empty result
// means "no usable schedule stored" and callers fall back to cache/defaults.
export function scheduleToEntity(schedule) {
  return normalizeSchedule(schedule);
}

export function scheduleFromEntity(raw) {
  return normalizeSchedule(Array.isArray(raw) ? raw : []);
}

// Purchase-order receiving math — pure and deterministic.
// Mirrors the server-side rules in base44/functions/purchaseOrderAction/entry.ts
// (receive_items → receiveStatus) so the UI derives exactly what the backend will
// persist: per-line open/partial/received, backorder quantities left on a
// partially-received PO, and expected-vs-received cost variance.

export const EPS = 0.005; // same tolerance the backend uses on receipt checks

const num = (v, fallback = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};
export const money = (v) => Math.round(num(v) * 100) / 100;
export const qty = (v) => Math.round(num(v) * 1000) / 1000;

export const LINE_STATUS = { OPEN: "open", PARTIAL: "partial", RECEIVED: "received" };
export const PO_ROLLUP = { OPEN: "open", PARTIAL: "partial", RECEIVED: "received" };

export const LINE_STATUS_LABELS = { open: "Open", partial: "Partial", received: "Received" };

// Map the model's rollup onto the entity status enum the backend persists.
export const toPoStatus = (rollup) =>
  rollup === PO_ROLLUP.RECEIVED ? "received"
    : rollup === PO_ROLLUP.PARTIAL ? "partially_received"
      : "sent";

// One PO line → derived receiving state.
// `poHasReceipt` controls backorder labeling: once a PO has had ANY receipt, the
// still-owed remainder is vendor backorder (CoreBridge semantics) rather than
// simply "not yet delivered".
export function deriveLineReceipt(line, { poHasReceipt } = {}) {
  const ordered = Math.max(0, qty(line?.quantity));
  const received = Math.max(0, qty(line?.quantity_received));
  const open = Math.max(0, qty(ordered - received));
  const unitCost = money(line?.unit_cost);
  const status = received <= EPS
    ? LINE_STATUS.OPEN
    : open <= EPS
      ? LINE_STATUS.RECEIVED
      : LINE_STATUS.PARTIAL;
  const anyReceipt = poHasReceipt === undefined ? received > EPS : poHasReceipt === true;
  const backordered = open > EPS && anyReceipt ? open : 0;
  const orderedCost = money(ordered * unitCost);
  const receivedCost = money(received * unitCost);
  const openCost = money(open * unitCost);
  return {
    ordered,
    received,
    open,
    backordered,
    status,
    unit_cost: unitCost,
    ordered_cost: orderedCost,
    received_cost: receivedCost,
    open_cost: openCost,
    // Expected-vs-received variance — negative means the vendor shipped short.
    variance_qty: qty(received - ordered),
    variance_cost: money(receivedCost - orderedCost),
    overdue: false, // stamped by derivePoReceipt when expected_date has passed
  };
}

// Whole PO → per-line states + rollup totals, mirroring receiveStatus() in the backend.
export function derivePoReceipt(po, { today } = {}) {
  const items = Array.isArray(po?.line_items) ? po.line_items : [];
  const anyReceived = items.some((r) => num(r?.quantity_received) > EPS);
  const todayStr = today || new Date().toISOString().slice(0, 10);
  const poOverdue = Boolean(clean(po?.expected_date) && clean(po?.expected_date) < todayStr
    && ["sent", "partially_received"].includes(clean(po?.status)));
  const lines = items.map((line, index) => ({
    index,
    description: clean(line?.description),
    inventory_item_id: clean(line?.inventory_item_id),
    ...deriveLineReceipt(line, { poHasReceipt: anyReceived }),
  }));
  for (const l of lines) l.overdue = poOverdue && l.open > EPS;

  const totals = lines.reduce((t, l) => ({
    ordered: qty(t.ordered + l.ordered),
    received: qty(t.received + l.received),
    open: qty(t.open + l.open),
    backordered: qty(t.backordered + l.backordered),
    ordered_cost: money(t.ordered_cost + l.ordered_cost),
    received_cost: money(t.received_cost + l.received_cost),
    open_cost: money(t.open_cost + l.open_cost),
    variance_qty: qty(t.variance_qty + l.variance_qty),
    variance_cost: money(t.variance_cost + l.variance_cost),
  }), {
    ordered: 0, received: 0, open: 0, backordered: 0,
    ordered_cost: 0, received_cost: 0, open_cost: 0,
    variance_qty: 0, variance_cost: 0,
  });

  const rollup = lines.length === 0
    ? PO_ROLLUP.OPEN
    : lines.every((l) => l.status === LINE_STATUS.RECEIVED)
      ? PO_ROLLUP.RECEIVED
      : anyReceived
        ? PO_ROLLUP.PARTIAL
        : PO_ROLLUP.OPEN;

  return {
    lines,
    totals,
    rollup,
    status: toPoStatus(rollup),
    any_received: anyReceived,
    complete: rollup === PO_ROLLUP.RECEIVED,
    overdue: poOverdue,
    percent_received: totals.ordered > 0 ? Math.min(100, Math.round((totals.received / totals.ordered) * 1000) / 10) : 0,
  };
}

const clean = (v) => String(v ?? "").trim();

// Turn the UI's {index: qty} input map into the exact lines payload the backend's
// receive_items action expects — [{index, quantity}] — with client-side checks
// that mirror the server's 400/409 guards so bad input never leaves the page.
export function buildReceiptLines(receiveQtys, receipt) {
  const lines = [];
  const errors = [];
  const byIndex = new Map((receipt?.lines || []).map((l) => [l.index, l]));
  for (const [rawIndex, rawQty] of Object.entries(receiveQtys || {})) {
    const index = Math.trunc(Number(rawIndex));
    const quantity = num(rawQty, NaN);
    if (!(quantity > 0)) continue; // blank/zero entries are ignored, like the old inline UI
    if (!byIndex.has(index)) { errors.push(`Receipt references a missing line (${index + 1}).`); continue; }
    const line = byIndex.get(index);
    if (quantity - line.open > EPS) {
      errors.push(`Receiving ${quantity} exceeds the open quantity on line ${index + 1} (${line.open} open).`);
      continue;
    }
    lines.push({ index, quantity: qty(quantity) });
  }
  if (lines.length === 0 && errors.length === 0) {
    errors.push("Enter a quantity to receive on at least one line.");
  }
  return { lines, errors };
}

// Plain-text receiving/backorder summary — used for vendor-notify (mailto body +
// clipboard copy). Deterministic output; no network side effects.
export function receivingSummaryText(po, receipt, { includeBackorderNote = true } = {}) {
  const r = receipt || derivePoReceipt(po);
  const out = [];
  out.push(`Purchase order ${clean(po?.po_number) || "(no number)"}${po?.vendor_name ? ` — ${clean(po.vendor_name)}` : ""}`);
  if (clean(po?.order_date)) out.push(`Ordered: ${clean(po.order_date)}`);
  if (clean(po?.expected_date)) out.push(`Expected: ${clean(po.expected_date)}${r.overdue ? " (OVERDUE)" : ""}`);
  out.push("");
  out.push("Lines:");
  for (const l of r.lines) {
    const parts = [`- ${l.description || `Line ${l.index + 1}`}: ordered ${l.ordered}, received ${l.received}`];
    if (l.open > EPS) parts.push(`open ${l.open}`);
    if (l.backordered > EPS) parts.push(`BACKORDER ${l.backordered}`);
    parts.push(`[${LINE_STATUS_LABELS[l.status] || l.status}]`);
    out.push(parts.join(", "));
  }
  out.push("");
  out.push(`Totals: ordered ${r.totals.ordered}, received ${r.totals.received}, open ${r.totals.open}${r.totals.backordered > EPS ? `, backordered ${r.totals.backordered}` : ""}`);
  if (includeBackorderNote && r.totals.backordered > EPS) {
    out.push("Please advise on the backorder ETA for the open quantities above.");
  }
  return out.join("\n");
}

// mailto: deep link for vendor notify — the backend has no vendor-email action,
// so the UI hands the operator a prefilled email instead.
export function vendorNotifyMailto(po, receipt) {
  const r = receipt || derivePoReceipt(po);
  const to = clean(po?.vendor_email);
  const subject = `${clean(po?.po_number) || "PO"} receiving${r.totals?.backordered > EPS ? " / backorder" : ""} update`;
  const body = receivingSummaryText(po, r);
  return { to, subject, body, href: `mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}` };
}

